    CRUpdateAllocationStrategy.add_member(:spot_price_capacity_optimized, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'SPOT_PRICE_CAPACITY_OPTIMIZED', traits: {"smithy.api#enumValue" => "SPOT_PRICE_CAPACITY_OPTIMIZED"}))
    CancelJobRequest.add_member(:job_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'jobId', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The Batch job ID of the job to cancel.</p>", "smithy.api#required" => {}}))
    CancelJobRequest.add_member(:reason, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'reason', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>A message to attach to the job that explains the reason for canceling it. This message is\n      returned by future <a>DescribeJobs</a> operations on the job. It is also\n      recorded in the Batch activity logs.</p>\n         <p>This parameter has as limit of 1024 characters.</p>", "smithy.api#required" => {}}))
    CancelJobRequest.type = Types::CancelJobRequest
    CancelJobResponse.type = Types::CancelJobResponse
    CapacityLimit.add_member(:max_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'maxCapacity', traits: {"smithy.api#documentation" => "<p>The maximum capacity available for the service environment. This value represents the maximum amount of resources that can be allocated to service jobs.</p>\n         <p>For example, <code>maxCapacity=50</code>, <code>capacityUnit=NUM_INSTANCES</code>. This indicates that the\n            maximum number of instances that can be run on this service environment is 50. You could\n            then run 5 SageMaker Training jobs that each use 10 instances. However, if you submit another job that\n            requires 10 instances, it will wait in the queue.</p>"}))
    CapacityLimit.add_member(:capacity_unit, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'capacityUnit', traits: {"smithy.api#documentation" => "<p>The unit of measure for the capacity limit. This defines how the maxCapacity value should be interpreted. For <code>SAGEMAKER_TRAINING</code> jobs, use <code>NUM_INSTANCES</code>.</p>"}))
    CapacityLimit.type = Types::CapacityLimit
