    ComputeEnvironmentDetail.add_member(:compute_environment_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'computeEnvironmentName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the compute environment. It can be up to 128 characters long. It can contain uppercase and\n lowercase letters, numbers, hyphens (-), and underscores (_).</p>", "smithy.api#required" => {}}))
    ComputeEnvironmentDetail.add_member(:compute_environment_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'computeEnvironmentArn', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the compute environment.</p>", "smithy.api#required" => {}}))
    ComputeEnvironmentDetail.add_member(:unmanagedv_cpus, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'unmanagedvCpus', traits: {"smithy.api#documentation" => "<p>The maximum number of VCPUs expected to be used for an unmanaged compute environment.</p>"}))
    ComputeEnvironmentDetail.add_member(:ecs_cluster_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ecsClusterArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the underlying Amazon ECS cluster that the compute environment uses.</p>"}))
    ComputeEnvironmentDetail.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagrisTagsMap, location_name: 'tags', traits: {"smithy.api#documentation" => "<p>The tags applied to the compute environment.</p>"}))
    ComputeEnvironmentDetail.add_member(:type, Smithy::Schema::Shapes::ShapeRef.new(shape: CEType, location_name: 'type', traits: {"smithy.api#documentation" => "<p>The type of the compute environment: <code>MANAGED</code> or <code>UNMANAGED</code>. For\n   more information, see <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/compute_environments.html\">Compute environments</a> in the <i>Batch User Guide</i>.</p>"}))
    ComputeEnvironmentDetail.add_member(:state, Smithy::Schema::Shapes::ShapeRef.new(shape: CEState, location_name: 'state', traits: {"smithy.api#documentation" => "<p>The state of the compute environment. The valid values are <code>ENABLED</code> or\n    <code>DISABLED</code>.</p>\n         <p>If the state is <code>ENABLED</code>, then the Batch scheduler can attempt to place jobs\n   from an associated job queue on the compute resources within the environment. If the compute\n   environment is managed, then it can scale its instances out or in automatically based on the job\n   queue demand.</p>\n         <p>If the state is <code>DISABLED</code>, then the Batch scheduler doesn't attempt to place\n   jobs within the environment. Jobs in a <code>STARTING</code> or <code>RUNNING</code> state\n   continue to progress normally. Managed compute environments in the <code>DISABLED</code> state\n   don't scale out. </p>\n         <note>\n            <p>Compute environments in a <code>DISABLED</code> state may continue to incur billing\n    charges. To prevent additional charges, turn off and then delete the compute environment. For\n    more information, see <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/compute_environment_parameters.html#compute_environment_state\">State</a> in the <i>Batch User Guide</i>.</p>\n         </note>\n         <p>When an instance is idle, the instance scales down to the <code>minvCpus</code> value.\n   However, the instance size doesn't change. For example, consider a <code>c5.8xlarge</code>\n   instance with a <code>minvCpus</code> value of <code>4</code> and a <code>desiredvCpus</code>\n   value of <code>36</code>. This instance doesn't scale down to a <code>c5.large</code>\n   instance.</p>"}))
    ComputeEnvironmentDetail.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: CEStatus, location_name: 'status', traits: {"smithy.api#documentation" => "<p>The current status of the compute environment (for example, <code>CREATING</code> or\n    <code>VALID</code>).</p>"}))
    ComputeEnvironmentDetail.add_member(:status_reason, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'statusReason', traits: {"smithy.api#documentation" => "<p>A short, human-readable string to provide additional details for the current status of the\n   compute environment.</p>"}))
    ComputeEnvironmentDetail.add_member(:compute_resources, Smithy::Schema::Shapes::ShapeRef.new(shape: ComputeResource, location_name: 'computeResources', traits: {"smithy.api#documentation" => "<p>The compute resources defined for the compute environment. For more information, see <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/compute_environments.html\">Compute environments</a> in\n   the <i>Batch User Guide</i>.</p>"}))
    ComputeEnvironmentDetail.add_member(:service_role, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'serviceRole', traits: {"smithy.api#documentation" => "<p>The service role that's associated with the compute environment that allows Batch to make\n   calls to Amazon Web Services API operations on your behalf. For more information, see <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/service_IAM_role.html\">Batch service IAM role</a> in the\n    <i>Batch User Guide</i>.</p>"}))
    ComputeEnvironmentDetail.add_member(:update_policy, Smithy::Schema::Shapes::ShapeRef.new(shape: UpdatePolicy, location_name: 'updatePolicy', traits: {"smithy.api#documentation" => "<p>Specifies the infrastructure update policy for the compute environment. For more information\n   about infrastructure updates, see <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/updating-compute-environments.html\">Updating compute environments</a> in the\n    <i>Batch User Guide</i>.</p>"}))
    ComputeEnvironmentDetail.add_member(:eks_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: EksConfiguration, location_name: 'eksConfiguration', traits: {"smithy.api#documentation" => "<p>The configuration for the Amazon EKS cluster that supports the Batch compute environment. Only\n   specify this parameter if the <code>containerOrchestrationType</code> is <code>EKS</code>.</p>"}))
    ComputeEnvironmentDetail.add_member(:container_orchestration_type, Smithy::Schema::Shapes::ShapeRef.new(shape: OrchestrationType, location_name: 'containerOrchestrationType', traits: {"smithy.api#documentation" => "<p>The orchestration type of the compute environment. The valid values are <code>ECS</code>\n   (default) or <code>EKS</code>.</p>"}))
    ComputeEnvironmentDetail.add_member(:uuid, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'uuid', traits: {"smithy.api#documentation" => "<p>Unique identifier for the compute environment.</p>"}))
    ComputeEnvironmentDetail.add_member(:context, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'context', traits: {"smithy.api#documentation" => "<p>Reserved.</p>"}))
    ComputeEnvironmentDetail.type = Types::ComputeEnvironmentDetail
    ComputeEnvironmentDetailList.member = Smithy::Schema::Shapes::ShapeRef.new(shape: ComputeEnvironmentDetail)
    ComputeEnvironmentOrder.add_member(:order, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'order', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The order of the compute environment. Compute environments are tried in ascending order. For\n   example, if two compute environments are associated with a job queue, the compute environment\n   with a lower <code>order</code> integer value is tried for job placement first.</p>", "smithy.api#required" => {}}))
    ComputeEnvironmentOrder.add_member(:compute_environment, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'computeEnvironment', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the compute environment.</p>", "smithy.api#required" => {}}))
    ComputeEnvironmentOrder.type = Types::ComputeEnvironmentOrder
    ComputeEnvironmentOrders.member = Smithy::Schema::Shapes::ShapeRef.new(shape: ComputeEnvironmentOrder)
    ComputeResource.add_member(:type, Smithy::Schema::Shapes::ShapeRef.new(shape: CRType, location_name: 'type', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The type of compute environment: <code>EC2</code>, <code>SPOT</code>, <code>FARGATE</code>,\n   or <code>FARGATE_SPOT</code>. For more information, see <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/compute_environments.html\">Compute environments</a> in the\n    <i>Batch User Guide</i>.</p>\n         <p> If you choose <code>SPOT</code>, you must also specify an Amazon EC2 Spot Fleet role with the\n    <code>spotIamFleetRole</code> parameter. For more information, see <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/spot_fleet_IAM_role.html\">Amazon EC2 spot fleet role</a> in the\n    <i>Batch User Guide</i>.</p>", "smithy.api#required" => {}}))
    ComputeResource.add_member(:allocation_strategy, Smithy::Schema::Shapes::ShapeRef.new(shape: CRAllocationStrategy, location_name: 'allocationStrategy', traits: {"smithy.api#documentation" => "<p>The allocation strategy to use for the compute resource if not enough instances of the best\n   fitting instance type can be allocated. This might be because of availability of the instance\n   type in the Region or <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/ec2-resource-limits.html\">Amazon EC2 service limits</a>. For more\n   information, see <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/allocation-strategies.html\">Allocation strategies</a> in the <i>Batch User Guide</i>.</p>\n         <note>\n            <p>This parameter isn't applicable to jobs that are running on Fargate resources. Don't specify it.</p>\n         </note>\n         <dl>\n            <dt>BEST_FIT (default)</dt>\n            <dd>\n               <p>Batch selects an instance type that best fits the needs of the jobs with a preference\n      for the lowest-cost instance type. If additional instances of the selected instance type\n      aren't available, Batch waits for the additional instances to be available. If there aren't\n      enough instances available or the user is reaching <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/ec2-resource-limits.html\">Amazon EC2 service limits</a>,\n      additional jobs aren't run until the currently running jobs are completed. This allocation\n      strategy keeps costs lower but can limit scaling. If you're using Spot Fleets with\n       <code>BEST_FIT</code>, the Spot Fleet IAM Role must be specified. Compute resources that use\n      a <code>BEST_FIT</code> allocation strategy don't support infrastructure updates and can't\n      update some parameters. For more information, see <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/updating-compute-environments.html\">Updating compute environments</a> in\n      the <i>Batch User Guide</i>.</p>\n            </dd>\n            <dt>BEST_FIT_PROGRESSIVE</dt>\n            <dd>\n               <p>Batch selects additional instance types that are large enough to meet the requirements\n      of the jobs in the queue. Its preference is for instance types with lower cost vCPUs. If\n      additional instances of the previously selected instance types aren't available, Batch\n      selects new instance types.</p>\n            </dd>\n            <dt>SPOT_CAPACITY_OPTIMIZED</dt>\n            <dd>\n               <p>Batch selects one or more instance types that are large enough to meet the requirements\n      of the jobs in the queue. Its preference is for instance types that are less likely to be\n      interrupted. This allocation strategy is only available for Spot Instance compute\n      resources.</p>\n            </dd>\n            <dt>SPOT_PRICE_CAPACITY_OPTIMIZED</dt>\n            <dd>\n               <p>The price and capacity optimized allocation strategy looks at both price and capacity to\n      select the Spot Instance pools that are the least likely to be interrupted and have the lowest\n      possible price. This allocation strategy is only available for Spot Instance compute\n      resources.</p>\n            </dd>\n         </dl>\n         <p>With <code>BEST_FIT_PROGRESSIVE</code>,<code>SPOT_CAPACITY_OPTIMIZED</code> and\n    <code>SPOT_PRICE_CAPACITY_OPTIMIZED</code> (recommended) strategies using On-Demand or Spot \n    Instances, and the <code>BEST_FIT</code> strategy using Spot Instances, Batch might need to \n    exceed <code>maxvCpus</code> to meet your capacity requirements. In this event, Batch never \n    exceeds <code>maxvCpus</code> by more than a single instance.</p>"}))
    ComputeResource.add_member(:minv_cpus, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'minvCpus', traits: {"smithy.api#documentation" => "<p>The minimum number of vCPUs that a compute environment should maintain (even if the compute \n   environment is <code>DISABLED</code>).</p>\n         <note>\n            <p>This parameter isn't applicable to jobs that are running on Fargate resources. Don't specify it.</p>\n         </note>"}))
    ComputeResource.add_member(:maxv_cpus, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'maxvCpus', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The maximum number of vCPUs that a compute environment can support.</p>\n         <note>\n            <p>With <code>BEST_FIT_PROGRESSIVE</code>,<code>SPOT_CAPACITY_OPTIMIZED</code> and\n     <code>SPOT_PRICE_CAPACITY_OPTIMIZED</code> (recommended) strategies using On-Demand or Spot Instances, \n     and the <code>BEST_FIT</code> strategy using Spot Instances, Batch might need to exceed\n     <code>maxvCpus</code> to meet your capacity requirements. In this event, Batch never exceeds\n     <code>maxvCpus</code> by more than a single instance.</p>\n         </note>", "smithy.api#required" => {}}))
    ComputeResource.add_member(:desiredv_cpus, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'desiredvCpus', traits: {"smithy.api#documentation" => "<p>The desired number of vCPUS in the compute environment. Batch modifies this value between \n   the minimum and maximum values based on job queue demand.</p>\n         <note>\n            <p>This parameter isn't applicable to jobs that are running on Fargate resources. Don't specify it.</p>\n         </note>"}))
    ComputeResource.add_member(:instance_types, Smithy::Schema::Shapes::ShapeRef.new(shape: StringList, location_name: 'instanceTypes', traits: {"smithy.api#documentation" => "<p>The instances types that can be launched. You can specify instance families to launch any\n   instance type within those families (for example, <code>c5</code> or <code>p3</code>), or you can\n   specify specific sizes within a family (such as <code>c5.8xlarge</code>). You can also choose\n    <code>optimal</code> to select instance types (from the C4, M4, and R4 instance families) that\n   match the demand of your job queues.</p>\n         <note>\n            <p>This parameter isn't applicable to jobs that are running on Fargate resources. Don't specify it.</p>\n         </note>\n         <note>\n            <p>When you create a compute environment, the instance types that you select for the compute environment must\n    share the same architecture. For example, you can't mix x86 and ARM instances in the same compute\n    environment.</p>\n         </note>\n         <note>\n            <p>Currently, <code>optimal</code> uses instance types from the C4, M4, and R4 instance\n    families. In Regions that don't have instance types from those instance families, instance types\n    from the C5, M5, and R5 instance families are used.</p>\n         </note>"}))
    ComputeResource.add_member(:image_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'imageId', traits: {"smithy.api#deprecated" => {"message" => "This field is deprecated, use ec2Configuration[].imageIdOverride instead."}, "smithy.api#documentation" => "<p>The Amazon Machine Image (AMI) ID used for instances launched in the compute environment.\n   This parameter is overridden by the <code>imageIdOverride</code> member of the\n    <code>Ec2Configuration</code> structure.</p>\n         <note>\n            <p>This parameter isn't applicable to jobs that are running on Fargate resources. Don't specify it.</p>\n         </note>\n         <note>\n            <p>The AMI that you choose for a compute environment must match the architecture of the instance types that\n    you intend to use for that compute environment. For example, if your compute environment uses A1 instance types,\n    the compute resource AMI that you choose must support ARM instances. Amazon ECS vends both x86 and ARM versions of the\n    Amazon ECS-optimized Amazon Linux 2 AMI. For more information, see <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/ecs-optimized_AMI.html#ecs-optimized-ami-linux-variants.html\">Amazon ECS-optimized\n    Amazon Linux 2 AMI</a>\n    in the <i>Amazon Elastic Container Service Developer Guide</i>.</p>\n         </note>"}))
    ComputeResource.add_member(:subnets, Smithy::Schema::Shapes::ShapeRef.new(shape: StringList, location_name: 'subnets', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The VPC subnets where the compute resources are launched. These subnets must be within the\n   same VPC. Fargate compute resources can contain up to 16 subnets. For more information, see\n    <a href=\"https://docs.aws.amazon.com/vpc/latest/userguide/VPC_Subnets.html\">VPCs and subnets</a>\n   in the <i>Amazon VPC User Guide</i>.</p>\n         <note>\n            <p>Batch on Amazon EC2 and Batch on Amazon EKS support Local Zones. For more information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/using-regions-availability-zones.html#concepts-local-zones\"> Local\n     Zones</a> in the <i>Amazon EC2 User Guide for Linux Instances</i>, <a href=\"https://docs.aws.amazon.com/eks/latest/userguide/local-zones.html\">Amazon EKS and Amazon Web Services Local\n     Zones</a> in the <i>Amazon EKS User Guide</i> and <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/cluster-regions-zones.html#clusters-local-zones\"> Amazon ECS\n     clusters in Local Zones, Wavelength Zones, and Amazon Web Services Outposts</a> in the <i>Amazon ECS\n     Developer Guide</i>.</p>\n            <p>Batch on Fargate doesn't currently support Local Zones.</p>\n         </note>", "smithy.api#required" => {}}))
    ComputeResource.add_member(:security_group_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: StringList, location_name: 'securityGroupIds', traits: {"smithy.api#documentation" => "<p>The Amazon EC2 security groups that are associated with instances launched in the compute\n   environment. One or more security groups must be specified, either in\n    <code>securityGroupIds</code> or using a launch template referenced in\n    <code>launchTemplate</code>. This parameter is required for jobs that are running on Fargate\n   resources and must contain at least one security group. Fargate doesn't support launch\n   templates. If security groups are specified using both <code>securityGroupIds</code> and\n    <code>launchTemplate</code>, the values in <code>securityGroupIds</code> are used.</p>"}))
    ComputeResource.add_member(:ec2_key_pair, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ec2KeyPair', traits: {"smithy.api#documentation" => "<p>The Amazon EC2 key pair that's used for instances launched in the compute environment. You can\n   use this key pair to log in to your instances with SSH.</p>\n         <note>\n            <p>This parameter isn't applicable to jobs that are running on Fargate resources. Don't specify it.</p>\n         </note>"}))
    ComputeResource.add_member(:instance_role, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'instanceRole', traits: {"smithy.api#documentation" => "<p>The Amazon ECS instance profile applied to Amazon EC2 instances in a compute environment. This\n   parameter is required for Amazon EC2 instances types. You can specify the short name or full Amazon Resource Name (ARN)\n   of an instance profile. For example, <code>\n               <i>ecsInstanceRole</i>\n            </code> or\n     <code>arn:aws:iam::<i><aws_account_id></i>:instance-profile/<i>ecsInstanceRole</i>\n            </code>.\n   For more information, see <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/instance_IAM_role.html\">Amazon ECS instance role</a> in the <i>Batch User Guide</i>.</p>\n         <note>\n            <p>This parameter isn't applicable to jobs that are running on Fargate resources. Don't specify it.</p>\n         </note>"}))
    ComputeResource.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagsMap, location_name: 'tags', traits: {"smithy.api#documentation" => "<p>Key-value pair tags to be applied to Amazon EC2 resources that are launched in the compute\n   environment. For Batch, these take the form of <code>\"String1\": \"String2\"</code>, where\n    <code>String1</code> is the tag key and <code>String2</code> is the tag value (for example,\n    <code>{ \"Name\": \"Batch Instance - C4OnDemand\" }</code>). This is helpful for recognizing your\n   Batch instances in the Amazon EC2 console. Updating these tags requires an infrastructure update to\n   the compute environment. For more information, see <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/updating-compute-environments.html\">Updating compute environments</a> in the\n    <i>Batch User Guide</i>. These tags aren't seen when using the Batch\n    <code>ListTagsForResource</code> API operation.</p>\n         <note>\n            <p>This parameter isn't applicable to jobs that are running on Fargate resources. Don't specify it.</p>\n         </note>"}))
    ComputeResource.add_member(:placement_group, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'placementGroup', traits: {"smithy.api#documentation" => "<p>The Amazon EC2 placement group to associate with your compute resources. If you intend to submit\n   multi-node parallel jobs to your compute environment, you should consider creating a cluster\n   placement group and associate it with your compute resources. This keeps your multi-node parallel\n   job on a logical grouping of instances within a single Availability Zone with high network flow\n   potential. For more information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/placement-groups.html\">Placement groups</a> in the\n    <i>Amazon EC2 User Guide for Linux Instances</i>.</p>\n         <note>\n            <p>This parameter isn't applicable to jobs that are running on Fargate resources. Don't specify it.</p>\n         </note>"}))
    ComputeResource.add_member(:bid_percentage, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'bidPercentage', traits: {"smithy.api#documentation" => "<p>The maximum percentage that a Spot Instance price can be when compared with the On-Demand\n   price for that instance type before instances are launched. For example, if your maximum\n   percentage is 20%, then the Spot price must be less than 20% of the current On-Demand price for\n   that Amazon EC2 instance. You always pay the lowest (market) price and never more than your maximum\n   percentage. If you leave this field empty, the default value is 100% of the On-Demand\n   price. For most use cases, we recommend leaving this field empty.</p>\n         <note>\n            <p>This parameter isn't applicable to jobs that are running on Fargate resources. Don't specify it.</p>\n         </note>"}))
    ComputeResource.add_member(:spot_iam_fleet_role, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'spotIamFleetRole', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the Amazon EC2 Spot Fleet IAM role applied to a <code>SPOT</code> compute\n   environment. This role is required if the allocation strategy set to <code>BEST_FIT</code> or if\n   the allocation strategy isn't specified. For more information, see <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/spot_fleet_IAM_role.html\">Amazon EC2 spot fleet role</a> in the\n    <i>Batch User Guide</i>.</p>\n         <note>\n            <p>This parameter isn't applicable to jobs that are running on Fargate resources. Don't specify it.</p>\n         </note>\n         <important>\n            <p>To tag your Spot Instances on creation, the Spot Fleet IAM role specified here must use\n    the newer <b>AmazonEC2SpotFleetTaggingRole</b> managed policy. The\n    previously recommended <b>AmazonEC2SpotFleetRole</b> managed policy\n    doesn't have the required permissions to tag Spot Instances. For more information, see <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/troubleshooting.html#spot-instance-no-tag\">Spot instances\n     not tagged on creation</a> in the <i>Batch User Guide</i>.</p>\n         </important>"}))
    ComputeResource.add_member(:launch_template, Smithy::Schema::Shapes::ShapeRef.new(shape: LaunchTemplateSpecification, location_name: 'launchTemplate', traits: {"smithy.api#documentation" => "<p>The launch template to use for your compute resources. Any other compute resource parameters\n   that you specify in a <a href=\"https://docs.aws.amazon.com/batch/latest/APIReference/API_CreateComputeEnvironment.html\">CreateComputeEnvironment</a> API operation override the same parameters in the launch\n   template. You must specify either the launch template ID or launch template name in the request,\n   but not both. For more information, see <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/launch-templates.html\">Launch template support</a> in the\n    <i>Batch User Guide</i>.</p>\n         <note>\n            <p>This parameter isn't applicable to jobs that are running on Fargate resources. Don't specify it.</p>\n         </note>"}))
    ComputeResource.add_member(:ec2_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: Ec2ConfigurationList, location_name: 'ec2Configuration', traits: {"smithy.api#documentation" => "<p>Provides information that's used to select Amazon Machine Images (AMIs) for Amazon EC2 instances\n   in the compute environment. If <code>Ec2Configuration</code> isn't specified, the default is\n    <code>ECS_AL2</code>.</p>\n         <p>One or two values can be provided.</p>\n         <note>\n            <p>This parameter isn't applicable to jobs that are running on Fargate resources. Don't specify it.</p>\n         </note>"}))
    ComputeResource.type = Types::ComputeResource
    ComputeResourceUpdate.add_member(:minv_cpus, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'minvCpus', traits: {"smithy.api#documentation" => "<p>The minimum number of vCPUs that an environment should maintain (even if the compute environment \n   is <code>DISABLED</code>).</p>\n         <note>\n            <p>This parameter isn't applicable to jobs that are running on Fargate resources. Don't specify it.</p>\n         </note>"}))
    ComputeResourceUpdate.add_member(:maxv_cpus, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'maxvCpus', traits: {"smithy.api#documentation" => "<p>The maximum number of Amazon EC2 vCPUs that an environment can reach.</p>\n         <note>\n            <p>With <code>BEST_FIT_PROGRESSIVE</code>,<code>SPOT_CAPACITY_OPTIMIZED</code> and\n     <code>SPOT_PRICE_CAPACITY_OPTIMIZED</code> (recommended) strategies using On-Demand or Spot \n     Instances, and the <code>BEST_FIT</code> strategy using Spot Instances, Batch might need to \n     exceed <code>maxvCpus</code> to meet your capacity requirements. In this event, Batch never \n     exceeds <code>maxvCpus</code> by more than a single instance.</p>\n         </note>"}))
    ComputeResourceUpdate.add_member(:desiredv_cpus, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'desiredvCpus', traits: {"smithy.api#documentation" => "<p>The desired number of vCPUS in the compute environment. Batch modifies this value between \n   the minimum and maximum values based on job queue demand.</p>\n         <note>\n            <p>This parameter isn't applicable to jobs that are running on Fargate resources. Don't specify it.</p>\n         </note>\n         <note>\n            <p>Batch doesn't support changing the desired number of vCPUs of an existing compute\n    environment. Don't specify this parameter for compute environments using Amazon EKS clusters.</p>\n         </note>\n         <note>\n            <p>When you update the <code>desiredvCpus</code> setting, the value must be between the\n     <code>minvCpus</code> and <code>maxvCpus</code> values. </p>\n            <p>Additionally, the updated <code>desiredvCpus</code> value must be greater than or equal to\n    the current <code>desiredvCpus</code> value. For more information, see <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/troubleshooting.html#error-desired-vcpus-update\">Troubleshooting\n     Batch</a> in the <i>Batch User Guide</i>.</p>\n         </note>"}))
    ComputeResourceUpdate.add_member(:subnets, Smithy::Schema::Shapes::ShapeRef.new(shape: StringList, location_name: 'subnets', traits: {"smithy.api#documentation" => "<p>The VPC subnets where the compute resources are launched. Fargate compute resources can\n   contain up to 16 subnets. For Fargate compute resources, providing an empty list will be\n   handled as if this parameter wasn't specified and no change is made. For Amazon EC2 compute resources,\n   providing an empty list removes the VPC subnets from the compute resource. For more information,\n   see <a href=\"https://docs.aws.amazon.com/vpc/latest/userguide/VPC_Subnets.html\">VPCs and\n    subnets</a> in the <i>Amazon VPC User Guide</i>.</p>\n         <p>When updating a compute environment, changing the VPC subnets requires an infrastructure\n   update of the compute environment. For more information, see <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/updating-compute-environments.html\">Updating compute environments</a> in the\n    <i>Batch User Guide</i>.</p>\n         <note>\n            <p>Batch on Amazon EC2 and Batch on Amazon EKS support Local Zones. For more information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/using-regions-availability-zones.html#concepts-local-zones\"> Local\n     Zones</a> in the <i>Amazon EC2 User Guide for Linux Instances</i>, <a href=\"https://docs.aws.amazon.com/eks/latest/userguide/local-zones.html\">Amazon EKS and Amazon Web Services Local\n     Zones</a> in the <i>Amazon EKS User Guide</i> and <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/cluster-regions-zones.html#clusters-local-zones\"> Amazon ECS\n     clusters in Local Zones, Wavelength Zones, and Amazon Web Services Outposts</a> in the <i>Amazon ECS\n     Developer Guide</i>.</p>\n            <p>Batch on Fargate doesn't currently support Local Zones.</p>\n         </note>"}))
    ComputeResourceUpdate.add_member(:security_group_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: StringList, location_name: 'securityGroupIds', traits: {"smithy.api#documentation" => "<p>The Amazon EC2 security groups that are associated with instances launched in the compute\n   environment. This parameter is required for Fargate compute resources, where it can contain up\n   to 5 security groups. For Fargate compute resources, providing an empty list is handled as if\n   this parameter wasn't specified and no change is made. For Amazon EC2 compute resources, providing an\n   empty list removes the security groups from the compute resource.</p>\n         <p>When updating a compute environment, changing the Amazon EC2 security groups requires an\n   infrastructure update of the compute environment. For more information, see <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/updating-compute-environments.html\">Updating compute\n    environments</a> in the <i>Batch User Guide</i>.</p>"}))
    ComputeResourceUpdate.add_member(:allocation_strategy, Smithy::Schema::Shapes::ShapeRef.new(shape: CRUpdateAllocationStrategy, location_name: 'allocationStrategy', traits: {"smithy.api#documentation" => "<p>The allocation strategy to use for the compute resource if there's not enough instances of\n   the best fitting instance type that can be allocated. This might be because of availability of\n   the instance type in the Region or <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/ec2-resource-limits.html\">Amazon EC2 service limits</a>. For more\n   information, see <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/allocation-strategies.html\">Allocation strategies</a> in the <i>Batch User Guide</i>.</p>\n         <p>When updating a compute environment, changing the allocation strategy requires an\n   infrastructure update of the compute environment. For more information, see <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/updating-compute-environments.html\">Updating compute\n    environments</a> in the <i>Batch User Guide</i>. <code>BEST_FIT</code> isn't\n   supported when updating a compute environment.</p>\n         <note>\n            <p>This parameter isn't applicable to jobs that are running on Fargate resources. Don't specify it.</p>\n         </note>\n         <dl>\n            <dt>BEST_FIT_PROGRESSIVE</dt>\n            <dd>\n               <p>Batch selects additional instance types that are large enough to meet the requirements\n      of the jobs in the queue. Its preference is for instance types with lower cost vCPUs. If\n      additional instances of the previously selected instance types aren't available, Batch\n      selects new instance types.</p>\n            </dd>\n            <dt>SPOT_CAPACITY_OPTIMIZED</dt>\n            <dd>\n               <p>Batch selects one or more instance types that are large enough to meet the requirements\n      of the jobs in the queue. Its preference is for instance types that are less likely to be\n      interrupted. This allocation strategy is only available for Spot Instance compute\n      resources.</p>\n            </dd>\n            <dt>SPOT_PRICE_CAPACITY_OPTIMIZED</dt>\n            <dd>\n               <p>The price and capacity optimized allocation strategy looks at both price and capacity to\n      select the Spot Instance pools that are the least likely to be interrupted and have the lowest\n      possible price. This allocation strategy is only available for Spot Instance compute\n      resources.</p>\n            </dd>\n         </dl>\n         <p>With <code>BEST_FIT_PROGRESSIVE</code>,<code>SPOT_CAPACITY_OPTIMIZED</code> and\n    <code>SPOT_PRICE_CAPACITY_OPTIMIZED</code> (recommended) strategies using On-Demand or Spot Instances, \n    and the <code>BEST_FIT</code> strategy using Spot Instances, Batch might need to exceed\n    <code>maxvCpus</code> to meet your capacity requirements. In this event, Batch never exceeds\n    <code>maxvCpus</code> by more than a single instance.</p>"}))
    ComputeResourceUpdate.add_member(:instance_types, Smithy::Schema::Shapes::ShapeRef.new(shape: StringList, location_name: 'instanceTypes', traits: {"smithy.api#documentation" => "<p>The instances types that can be launched. You can specify instance families to launch any\n   instance type within those families (for example, <code>c5</code> or <code>p3</code>), or you can\n   specify specific sizes within a family (such as <code>c5.8xlarge</code>). You can also choose\n    <code>optimal</code> to select instance types (from the C4, M4, and R4 instance families) that\n   match the demand of your job queues.</p>\n         <p>When updating a compute environment, changing this setting requires an infrastructure update\n   of the compute environment. For more information, see <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/updating-compute-environments.html\">Updating compute environments</a> in the\n    <i>Batch User Guide</i>.</p>\n         <note>\n            <p>This parameter isn't applicable to jobs that are running on Fargate resources. Don't specify it.</p>\n         </note>\n         <note>\n            <p>When you create a compute environment, the instance types that you select for the compute environment must\n    share the same architecture. For example, you can't mix x86 and ARM instances in the same compute\n    environment.</p>\n         </note>\n         <note>\n            <p>Currently, <code>optimal</code> uses instance types from the C4, M4, and R4 instance\n    families. In Regions that don't have instance types from those instance families, instance types\n    from the C5, M5, and R5 instance families are used.</p>\n         </note>"}))
    ComputeResourceUpdate.add_member(:ec2_key_pair, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ec2KeyPair', traits: {"smithy.api#documentation" => "<p>The Amazon EC2 key pair that's used for instances launched in the compute environment. You can\n   use this key pair to log in to your instances with SSH. To remove the Amazon EC2 key pair, set this\n   value to an empty string.</p>\n         <p>When updating a compute environment, changing the Amazon EC2 key pair requires an infrastructure\n   update of the compute environment. For more information, see <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/updating-compute-environments.html\">Updating compute environments</a> in the\n    <i>Batch User Guide</i>.</p>\n         <note>\n            <p>This parameter isn't applicable to jobs that are running on Fargate resources. Don't specify it.</p>\n         </note>"}))
    ComputeResourceUpdate.add_member(:instance_role, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'instanceRole', traits: {"smithy.api#documentation" => "<p>The Amazon ECS instance profile applied to Amazon EC2 instances in a compute environment.\n   Required for Amazon EC2 instances. You can specify the short name or full Amazon Resource Name (ARN) of an instance\n   profile. For example, <code>\n               <i>ecsInstanceRole</i>\n            </code> or\n     <code>arn:aws:iam::<i><aws_account_id></i>:instance-profile/<i>ecsInstanceRole</i>\n            </code>.\n   For more information, see <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/instance_IAM_role.html\">Amazon ECS instance role</a> in the <i>Batch User Guide</i>.</p>\n         <p>When updating a compute environment, changing this setting requires an infrastructure update\n   of the compute environment. For more information, see <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/updating-compute-environments.html\">Updating compute environments</a> in the\n    <i>Batch User Guide</i>.</p>\n         <note>\n            <p>This parameter isn't applicable to jobs that are running on Fargate resources. Don't specify it.</p>\n         </note>"}))
    ComputeResourceUpdate.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagsMap, location_name: 'tags', traits: {"smithy.api#documentation" => "<p>Key-value pair tags to be applied to Amazon EC2 resources that are launched in the compute\n   environment. For Batch, these take the form of <code>\"String1\": \"String2\"</code>, where\n    <code>String1</code> is the tag key and <code>String2</code> is the tag value (for example,\n    <code>{ \"Name\": \"Batch Instance - C4OnDemand\" }</code>). This is helpful for recognizing your\n   Batch instances in the Amazon EC2 console. These tags aren't seen when using the Batch\n    <code>ListTagsForResource</code> API operation.</p>\n         <p>When updating a compute environment, changing this setting requires an infrastructure update\n   of the compute environment. For more information, see <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/updating-compute-environments.html\">Updating compute environments</a> in the\n    <i>Batch User Guide</i>.</p>\n         <note>\n            <p>This parameter isn't applicable to jobs that are running on Fargate resources. Don't specify it.</p>\n         </note>"}))
    ComputeResourceUpdate.add_member(:placement_group, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'placementGroup', traits: {"smithy.api#documentation" => "<p>The Amazon EC2 placement group to associate with your compute resources. If you intend to submit\n   multi-node parallel jobs to your compute environment, you should consider creating a cluster\n   placement group and associate it with your compute resources. This keeps your multi-node parallel\n   job on a logical grouping of instances within a single Availability Zone with high network flow\n   potential. For more information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/placement-groups.html\">Placement groups</a> in the\n    <i>Amazon EC2 User Guide for Linux Instances</i>.</p>\n         <p>When updating a compute environment, changing the placement group requires an infrastructure\n   update of the compute environment. For more information, see <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/updating-compute-environments.html\">Updating compute environments</a> in the\n    <i>Batch User Guide</i>.</p>\n         <note>\n            <p>This parameter isn't applicable to jobs that are running on Fargate resources. Don't specify it.</p>\n         </note>"}))
    ComputeResourceUpdate.add_member(:bid_percentage, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'bidPercentage', traits: {"smithy.api#documentation" => "<p>The maximum percentage that a Spot Instance price can be when compared with the On-Demand\n   price for that instance type before instances are launched. For example, if your maximum\n   percentage is 20%, the Spot price must be less than 20% of the current On-Demand price for that\n   Amazon EC2 instance. You always pay the lowest (market) price and never more than your maximum\n   percentage. For most use cases, we recommend leaving this field empty.</p>\n         <p>When updating a compute environment, changing the bid percentage requires an infrastructure\n   update of the compute environment. For more information, see <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/updating-compute-environments.html\">Updating compute environments</a> in the\n    <i>Batch User Guide</i>.</p>\n         <note>\n            <p>This parameter isn't applicable to jobs that are running on Fargate resources. Don't specify it.</p>\n         </note>"}))
    ComputeResourceUpdate.add_member(:launch_template, Smithy::Schema::Shapes::ShapeRef.new(shape: LaunchTemplateSpecification, location_name: 'launchTemplate', traits: {"smithy.api#documentation" => "<p>The updated launch template to use for your compute resources. You must specify either the\n   launch template ID or launch template name in the request, but not both. For more information,\n   see <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/launch-templates.html\">Launch template\n    support</a> in the <i>Batch User Guide</i>. To remove the custom launch\n   template and use the default launch template, set <code>launchTemplateId</code> or\n    <code>launchTemplateName</code> member of the launch template specification to an empty string.\n   Removing the launch template from a compute environment will not remove the AMI specified in the\n   launch template. In order to update the AMI specified in a launch template, the\n    <code>updateToLatestImageVersion</code> parameter must be set to <code>true</code>.</p>\n         <p>When updating a compute environment, changing the launch template requires an infrastructure\n   update of the compute environment. For more information, see <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/updating-compute-environments.html\">Updating compute environments</a> in the\n    <i>Batch User Guide</i>.</p>\n         <note>\n            <p>This parameter isn't applicable to jobs that are running on Fargate resources. Don't specify it.</p>\n         </note>"}))
    ComputeResourceUpdate.add_member(:ec2_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: Ec2ConfigurationList, location_name: 'ec2Configuration', traits: {"smithy.api#documentation" => "<p>Provides information used to select Amazon Machine Images (AMIs) for Amazon EC2 instances in the\n   compute environment. If <code>Ec2Configuration</code> isn't specified, the default is\n    <code>ECS_AL2</code>.</p>\n         <p>When updating a compute environment, changing this setting requires an infrastructure update\n   of the compute environment. For more information, see <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/updating-compute-environments.html\">Updating compute environments</a> in the\n    <i>Batch User Guide</i>. To remove the Amazon EC2 configuration and any custom AMI ID\n   specified in <code>imageIdOverride</code>, set this value to an empty string.</p>\n         <p>One or two values can be provided.</p>\n         <note>\n            <p>This parameter isn't applicable to jobs that are running on Fargate resources. Don't specify it.</p>\n         </note>"}))
    ComputeResourceUpdate.add_member(:update_to_latest_image_version, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'updateToLatestImageVersion', traits: {"smithy.api#documentation" => "<p>Specifies whether the AMI ID is updated to the latest one that's supported by Batch when\n   the compute environment has an infrastructure update. The default value is\n   <code>false</code>.</p>\n         <note>\n            <p>An AMI ID can either be specified in the <code>imageId</code> or\n     <code>imageIdOverride</code> parameters or be determined by the launch template that's\n    specified in the <code>launchTemplate</code> parameter. If an AMI ID is specified any of these\n    ways, this parameter is ignored. For more information about to update AMI IDs during an\n    infrastructure update, see <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/updating-compute-environments.html#updating-compute-environments-ami\">Updating\n     the AMI ID</a> in the <i>Batch User Guide</i>.</p>\n         </note>\n         <p>When updating a compute environment, changing this setting requires an infrastructure update\n   of the compute environment. For more information, see <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/updating-compute-environments.html\">Updating compute environments</a> in the\n    <i>Batch User Guide</i>.</p>"}))
    ComputeResourceUpdate.add_member(:type, Smithy::Schema::Shapes::ShapeRef.new(shape: CRType, location_name: 'type', traits: {"smithy.api#documentation" => "<p>The type of compute environment: <code>EC2</code>, <code>SPOT</code>, <code>FARGATE</code>,\n   or <code>FARGATE_SPOT</code>. For more information, see <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/compute_environments.html\">Compute environments</a> in the\n    <i>Batch User Guide</i>.</p>\n         <p> If you choose <code>SPOT</code>, you must also specify an Amazon EC2 Spot Fleet role with the\n    <code>spotIamFleetRole</code> parameter. For more information, see <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/spot_fleet_IAM_role.html\">Amazon EC2 spot fleet role</a> in the\n    <i>Batch User Guide</i>.</p>\n         <p>When updating a compute environment, changing the type of a compute environment requires an\n   infrastructure update of the compute environment. For more information, see <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/updating-compute-environments.html\">Updating compute\n    environments</a> in the <i>Batch User Guide</i>.</p>"}))
    ComputeResourceUpdate.add_member(:image_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'imageId', traits: {"smithy.api#documentation" => "<p>The Amazon Machine Image (AMI) ID used for instances launched in the compute environment.\n   This parameter is overridden by the <code>imageIdOverride</code> member of the\n    <code>Ec2Configuration</code> structure. To remove the custom AMI ID and use the default AMI ID,\n   set this value to an empty string.</p>\n         <p>When updating a compute environment, changing the AMI ID requires an infrastructure update\n   of the compute environment. For more information, see <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/updating-compute-environments.html\">Updating compute environments</a> in the\n    <i>Batch User Guide</i>.</p>\n         <note>\n            <p>This parameter isn't applicable to jobs that are running on Fargate resources. Don't specify it.</p>\n         </note>\n         <note>\n            <p>The AMI that you choose for a compute environment must match the architecture of the instance types that\n    you intend to use for that compute environment. For example, if your compute environment uses A1 instance types,\n    the compute resource AMI that you choose must support ARM instances. Amazon ECS vends both x86 and ARM versions of the\n    Amazon ECS-optimized Amazon Linux 2 AMI. For more information, see <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/ecs-optimized_AMI.html#ecs-optimized-ami-linux-variants.html\">Amazon ECS-optimized\n    Amazon Linux 2 AMI</a>\n    in the <i>Amazon Elastic Container Service Developer Guide</i>.</p>\n         </note>"}))
    ComputeResourceUpdate.type = Types::ComputeResourceUpdate
    ConsumableResourceList.member = Smithy::Schema::Shapes::ShapeRef.new(shape: ConsumableResourceRequirement)
    ConsumableResourceProperties.add_member(:consumable_resource_list, Smithy::Schema::Shapes::ShapeRef.new(shape: ConsumableResourceList, location_name: 'consumableResourceList', traits: {"smithy.api#documentation" => "<p>The list of consumable resources required by a job.</p>"}))
    ConsumableResourceProperties.type = Types::ConsumableResourceProperties
    ConsumableResourceRequirement.add_member(:consumable_resource, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'consumableResource', traits: {"smithy.api#documentation" => "<p>The name or ARN of the consumable resource.</p>"}))
    ConsumableResourceRequirement.add_member(:quantity, Smithy::Schema::Shapes::ShapeRef.new(shape: Long, location_name: 'quantity', traits: {"smithy.api#documentation" => "<p>The quantity of the consumable resource that is needed.</p>"}))
    ConsumableResourceRequirement.type = Types::ConsumableResourceRequirement
    ConsumableResourceSummary.add_member(:consumable_resource_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'consumableResourceArn', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the consumable resource.</p>", "smithy.api#required" => {}}))
    ConsumableResourceSummary.add_member(:consumable_resource_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'consumableResourceName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the consumable resource.</p>", "smithy.api#required" => {}}))
    ConsumableResourceSummary.add_member(:total_quantity, Smithy::Schema::Shapes::ShapeRef.new(shape: Long, location_name: 'totalQuantity', traits: {"smithy.api#documentation" => "<p>The total amount of the consumable resource that is available.</p>"}))
    ConsumableResourceSummary.add_member(:in_use_quantity, Smithy::Schema::Shapes::ShapeRef.new(shape: Long, location_name: 'inUseQuantity', traits: {"smithy.api#documentation" => "<p>The amount of the consumable resource that is currently in use.</p>"}))
    ConsumableResourceSummary.add_member(:resource_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'resourceType', traits: {"smithy.api#documentation" => "<p>Indicates whether the resource is available to be re-used after a job completes. Can be \n            one of: </p>\n         <ul>\n            <li>\n               <p>\n                  <code>REPLENISHABLE</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>NON_REPLENISHABLE</code>\n               </p>\n            </li>\n         </ul>"}))
    ConsumableResourceSummary.type = Types::ConsumableResourceSummary
    ConsumableResourceSummaryList.member = Smithy::Schema::Shapes::ShapeRef.new(shape: ConsumableResourceSummary)
    ContainerDetail.add_member(:image, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'image', traits: {"smithy.api#documentation" => "<p>The image used to start the container.</p>"}))
    ContainerDetail.add_member(:vcpus, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'vcpus', traits: {"smithy.api#documentation" => "<p>The number of vCPUs reserved for the container. For jobs that run on Amazon EC2 resources, you\n   can specify the vCPU requirement for the job using <code>resourceRequirements</code>, but you\n   can't specify the vCPU requirements in both the <code>vcpus</code> and\n    <code>resourceRequirements</code> object. This parameter maps to <code>CpuShares</code> in the\n   <a href=\"https://docs.docker.com/engine/api/v1.23/#create-a-container\">Create a container</a> section of the <a href=\"https://docs.docker.com/engine/api/v1.23/\">Docker Remote API</a> and the\n    <code>--cpu-shares</code> option to <a href=\"https://docs.docker.com/engine/reference/run/\">docker run</a>. Each\n   vCPU is equivalent to 1,024 CPU shares. You must specify at least one vCPU. This is required but\n   can be specified in several places. It must be specified for each node at least once.</p>\n         <note>\n            <p>This parameter isn't applicable to jobs that run on Fargate resources. For jobs that run\n    on Fargate resources, you must specify the vCPU requirement for the job using\n     <code>resourceRequirements</code>.</p>\n         </note>"}))
    ContainerDetail.add_member(:memory, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'memory', traits: {"smithy.api#documentation" => "<p>For jobs running on Amazon EC2 resources that didn't specify memory requirements using\n    <code>resourceRequirements</code>, the number of MiB of memory reserved for the job. For other\n   jobs, including all run on Fargate resources, see <code>resourceRequirements</code>.</p>"}))
    ContainerDetail.add_member(:command, Smithy::Schema::Shapes::ShapeRef.new(shape: StringList, location_name: 'command', traits: {"smithy.api#documentation" => "<p>The command that's passed to the container.</p>"}))
    ContainerDetail.add_member(:job_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'jobRoleArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) that's associated with the job when run.</p>"}))
    ContainerDetail.add_member(:execution_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'executionRoleArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the execution role that Batch can assume. For more information,\n   see <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/execution-IAM-role.html\">Batch execution IAM\n    role</a> in the <i>Batch User Guide</i>.</p>"}))
    ContainerDetail.add_member(:volumes, Smithy::Schema::Shapes::ShapeRef.new(shape: Volumes, location_name: 'volumes', traits: {"smithy.api#documentation" => "<p>A list of volumes that are associated with the job.</p>"}))
    ContainerDetail.add_member(:environment, Smithy::Schema::Shapes::ShapeRef.new(shape: EnvironmentVariables, location_name: 'environment', traits: {"smithy.api#documentation" => "<p>The environment variables to pass to a container.</p>\n         <note>\n            <p>Environment variables cannot start with \"<code>AWS_BATCH</code>\". This naming\n convention is reserved for variables that Batch sets.</p>\n         </note>"}))
    ContainerDetail.add_member(:mount_points, Smithy::Schema::Shapes::ShapeRef.new(shape: MountPoints, location_name: 'mountPoints', traits: {"smithy.api#documentation" => "<p>The mount points for data volumes in your container.</p>"}))
    ContainerDetail.add_member(:readonly_root_filesystem, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'readonlyRootFilesystem', traits: {"smithy.api#documentation" => "<p>When this parameter is true, the container is given read-only access to its root file\n   system. This parameter maps to <code>ReadonlyRootfs</code> in the\n   <a href=\"https://docs.docker.com/engine/api/v1.23/#create-a-container\">Create a container</a> section of the <a href=\"https://docs.docker.com/engine/api/v1.23/\">Docker Remote API</a> and the\n    <code>--read-only</code> option to <a href=\"https://docs.docker.com/engine/reference/commandline/run/\">\n               <code>docker\n   run</code>\n            </a>.</p>"}))
    ContainerDetail.add_member(:ulimits, Smithy::Schema::Shapes::ShapeRef.new(shape: Ulimits, location_name: 'ulimits', traits: {"smithy.api#documentation" => "<p>A list of <code>ulimit</code> values to set in the container. This parameter maps to\n    <code>Ulimits</code> in the <a href=\"https://docs.docker.com/engine/api/v1.23/#create-a-container\">Create a container</a> section of the <a href=\"https://docs.docker.com/engine/api/v1.23/\">Docker Remote API</a>\n   and the <code>--ulimit</code> option to <a href=\"https://docs.docker.com/engine/reference/run/\">docker\n   run</a>.</p>\n         <note>\n            <p>This parameter isn't applicable to jobs that are running on Fargate resources.</p>\n         </note>"}))
    ContainerDetail.add_member(:privileged, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'privileged', traits: {"smithy.api#documentation" => "<p>When this parameter is true, the container is given elevated permissions on the host\n   container instance (similar to the <code>root</code> user). The default value is\n    <code>false</code>.</p>\n         <note>\n            <p>This parameter isn't applicable to jobs that are running on Fargate resources and\n    shouldn't be provided, or specified as <code>false</code>.</p>\n         </note>"}))
    ContainerDetail.add_member(:user, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'user', traits: {"smithy.api#documentation" => "<p>The user name to use inside the container. This parameter maps to <code>User</code> in the\n   <a href=\"https://docs.docker.com/engine/api/v1.23/#create-a-container\">Create a container</a> section of the <a href=\"https://docs.docker.com/engine/api/v1.23/\">Docker Remote API</a> and the <code>--user</code>\n   option to <a href=\"https://docs.docker.com/engine/reference/run/\">docker run</a>.</p>"}))
    ContainerDetail.add_member(:exit_code, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'exitCode', traits: {"smithy.api#documentation" => "<p>The exit code returned upon completion.</p>"}))
    ContainerDetail.add_member(:reason, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'reason', traits: {"smithy.api#documentation" => "<p>A short (255 max characters) human-readable string to provide additional details for a\n   running or stopped container.</p>"}))
    ContainerDetail.add_member(:container_instance_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'containerInstanceArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the container instance that the container is running on.</p>"}))
    ContainerDetail.add_member(:task_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'taskArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the Amazon ECS task that's associated with the container job. Each container\n   attempt receives a task ARN when they reach the <code>STARTING</code> status.</p>"}))
    ContainerDetail.add_member(:log_stream_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'logStreamName', traits: {"smithy.api#documentation" => "<p>The name of the Amazon CloudWatch Logs log stream that's associated with the container. The log group for\n   Batch jobs is <code>/aws/batch/job</code>. Each container attempt receives a log stream name\n   when they reach the <code>RUNNING</code> status.</p>"}))
    ContainerDetail.add_member(:instance_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'instanceType', traits: {"smithy.api#documentation" => "<p>The instance type of the underlying host infrastructure of a multi-node parallel job.</p>\n         <note>\n            <p>This parameter isn't applicable to jobs that are running on Fargate resources.</p>\n         </note>"}))
    ContainerDetail.add_member(:network_interfaces, Smithy::Schema::Shapes::ShapeRef.new(shape: NetworkInterfaceList, location_name: 'networkInterfaces', traits: {"smithy.api#documentation" => "<p>The network interfaces that are associated with the job.</p>"}))
    ContainerDetail.add_member(:resource_requirements, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceRequirements, location_name: 'resourceRequirements', traits: {"smithy.api#documentation" => "<p>The type and amount of resources to assign to a container. The supported resources include\n    <code>GPU</code>, <code>MEMORY</code>, and <code>VCPU</code>.</p>"}))
    ContainerDetail.add_member(:linux_parameters, Smithy::Schema::Shapes::ShapeRef.new(shape: LinuxParameters, location_name: 'linuxParameters', traits: {"smithy.api#documentation" => "<p>Linux-specific modifications that are applied to the container, such as details for device\n   mappings.</p>"}))
    ContainerDetail.add_member(:log_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: LogConfiguration, location_name: 'logConfiguration', traits: {"smithy.api#documentation" => "<p>The log configuration specification for the container.</p>\n         <p>This parameter maps to <code>LogConfig</code> in the <a href=\"https://docs.docker.com/engine/api/v1.23/#create-a-container\">Create a container</a>\n   section of the <a href=\"https://docs.docker.com/engine/api/v1.23/\">Docker Remote API</a> and the <code>--log-driver</code> option to <a href=\"https://docs.docker.com/engine/reference/run/\">docker run</a>. By default, containers use the same logging\n   driver that the Docker daemon uses. However, the container might use a different logging driver\n   than the Docker daemon by specifying a log driver with this parameter in the container\n   definition. To use a different logging driver for a container, the log system must be configured\n   properly on the container instance. Or, alternatively, it must be configured on a different log\n   server for remote logging options. For more information on the options for different supported\n   log drivers, see <a href=\"https://docs.docker.com/engine/admin/logging/overview/\">Configure\n    logging drivers</a> in the Docker documentation.</p>\n         <note>\n            <p>Batch currently supports a subset of the logging drivers available to the Docker daemon\n    (shown in the <a href=\"https://docs.aws.amazon.com/AWSCloudFormation/latest/UserGuide/aws-properties-batch-jobdefinition-containerproperties-logconfiguration.html\">LogConfiguration</a> data type). Additional log drivers might be available in future\n    releases of the Amazon ECS container agent.</p>\n         </note>\n         <p>This parameter requires version 1.18 of the Docker Remote API or greater on your\n container instance. To check the Docker Remote API version on your container instance, log in to your\n container instance and run the following command: <code>sudo docker version | grep \"Server API version\"</code>\n         </p>\n         <note>\n            <p>The Amazon ECS container agent running on a container instance must register the logging drivers\n    available on that instance with the <code>ECS_AVAILABLE_LOGGING_DRIVERS</code> environment\n    variable before containers placed on that instance can use these log configuration options. For\n    more information, see <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/ecs-agent-config.html\">Amazon ECS container agent\n     configuration</a> in the <i>Amazon Elastic Container Service Developer Guide</i>.</p>\n         </note>"}))
    ContainerDetail.add_member(:secrets, Smithy::Schema::Shapes::ShapeRef.new(shape: SecretList, location_name: 'secrets', traits: {"smithy.api#documentation" => "<p>The secrets to pass to the container. For more information, see <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/specifying-sensitive-data.html\">Specifying sensitive data</a> in the\n    <i>Batch User Guide</i>.</p>"}))
    ContainerDetail.add_member(:network_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: NetworkConfiguration, location_name: 'networkConfiguration', traits: {"smithy.api#documentation" => "<p>The network configuration for jobs that are running on Fargate resources. Jobs that are\n   running on Amazon EC2 resources must not specify this parameter.</p>"}))
    ContainerDetail.add_member(:fargate_platform_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: FargatePlatformConfiguration, location_name: 'fargatePlatformConfiguration', traits: {"smithy.api#documentation" => "<p>The platform configuration for jobs that are running on Fargate resources. Jobs that are\n   running on Amazon EC2 resources must not specify this parameter.</p>"}))
    ContainerDetail.add_member(:ephemeral_storage, Smithy::Schema::Shapes::ShapeRef.new(shape: EphemeralStorage, location_name: 'ephemeralStorage', traits: {"smithy.api#documentation" => "<p>The amount of ephemeral storage allocated for the task. This parameter is used to expand the\n   total amount of ephemeral storage available, beyond the default amount, for tasks hosted on\n   Fargate.</p>"}))
    ContainerDetail.add_member(:runtime_platform, Smithy::Schema::Shapes::ShapeRef.new(shape: RuntimePlatform, location_name: 'runtimePlatform', traits: {"smithy.api#documentation" => "<p>An object that represents the compute environment architecture for Batch jobs on\n   Fargate.</p>"}))
    ContainerDetail.add_member(:repository_credentials, Smithy::Schema::Shapes::ShapeRef.new(shape: RepositoryCredentials, location_name: 'repositoryCredentials', traits: {"smithy.api#documentation" => "<p>The private repository authentication credentials to use.</p>"}))
    ContainerDetail.add_member(:enable_execute_command, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'enableExecuteCommand', traits: {"smithy.api#documentation" => "<p>Determines whether execute command functionality is turned on for this task. If <code>true</code>, execute\n            command functionality is turned on all the containers in the task.</p>"}))
    ContainerDetail.type = Types::ContainerDetail
    ContainerOverrides.add_member(:vcpus, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'vcpus', traits: {"smithy.api#deprecated" => {"message" => "This field is deprecated, use resourceRequirements instead."}, "smithy.api#documentation" => "<p>This parameter is deprecated, use <code>resourceRequirements</code> to override the\n    <code>vcpus</code> parameter that's set in the job definition. It's not supported for jobs\n   running on Fargate resources. For jobs that run on Amazon EC2 resources, it overrides the\n    <code>vcpus</code> parameter set in the job definition, but doesn't override any vCPU\n   requirement specified in the <code>resourceRequirements</code> structure in the job definition.\n   To override vCPU requirements that are specified in the <code>resourceRequirements</code>\n   structure in the job definition, <code>resourceRequirements</code> must be specified in the\n    <code>SubmitJob</code> request, with <code>type</code> set to <code>VCPU</code> and\n    <code>value</code> set to the new value. For more information, see <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/troubleshooting.html#override-resource-requirements\">Can't override job\n    definition resource requirements</a> in the <i>Batch User Guide</i>.</p>"}))
    ContainerOverrides.add_member(:memory, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'memory', traits: {"smithy.api#deprecated" => {"message" => "This field is deprecated, use resourceRequirements instead."}, "smithy.api#documentation" => "<p>This parameter is deprecated, use <code>resourceRequirements</code> to override the memory\n   requirements specified in the job definition. It's not supported for jobs running on Fargate\n   resources. For jobs that run on Amazon EC2 resources, it overrides the <code>memory</code> parameter\n   set in the job definition, but doesn't override any memory requirement that's specified in the\n    <code>resourceRequirements</code> structure in the job definition. To override memory\n   requirements that are specified in the <code>resourceRequirements</code> structure in the job\n   definition, <code>resourceRequirements</code> must be specified in the <code>SubmitJob</code>\n   request, with <code>type</code> set to <code>MEMORY</code> and <code>value</code> set to the new\n   value. For more information, see <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/troubleshooting.html#override-resource-requirements\">Can't override job\n    definition resource requirements</a> in the <i>Batch User Guide</i>.</p>"}))
    ContainerOverrides.add_member(:command, Smithy::Schema::Shapes::ShapeRef.new(shape: StringList, location_name: 'command', traits: {"smithy.api#documentation" => "<p>The command to send to the container that overrides the default command from the Docker\n   image or the job definition.</p>\n         <note>\n            <p>This parameter can't contain an empty string.</p>\n         </note>"}))
    ContainerOverrides.add_member(:instance_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'instanceType', traits: {"smithy.api#documentation" => "<p>The instance type to use for a multi-node parallel job.</p>\n         <note>\n            <p>This parameter isn't applicable to single-node container jobs or jobs that run on Fargate\n    resources, and shouldn't be provided.</p>\n         </note>"}))
    ContainerOverrides.add_member(:environment, Smithy::Schema::Shapes::ShapeRef.new(shape: EnvironmentVariables, location_name: 'environment', traits: {"smithy.api#documentation" => "<p>The environment variables to send to the container. You can add new environment variables,\n   which are added to the container at launch, or you can override the existing environment\n   variables from the Docker image or the job definition.</p>\n         <note>\n            <p>Environment variables cannot start with \"<code>AWS_BATCH</code>\". This naming\n convention is reserved for variables that Batch sets.</p>\n         </note>"}))
    ContainerOverrides.add_member(:resource_requirements, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceRequirements, location_name: 'resourceRequirements', traits: {"smithy.api#documentation" => "<p>The type and amount of resources to assign to a container. This overrides the settings in\n   the job definition. The supported resources include <code>GPU</code>, <code>MEMORY</code>, and\n    <code>VCPU</code>.</p>"}))
    ContainerOverrides.type = Types::ContainerOverrides
    ContainerProperties.add_member(:image, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'image', traits: {"smithy.api#documentation" => "<p>Required. The image used to start a container. This string is passed directly to the\n   Docker daemon. Images in the Docker Hub registry are available by default. Other repositories are\n   specified with\n     <code>\n               <i>repository-url</i>/<i>image</i>:<i>tag</i>\n            </code>.\n   It can be 255 characters long. It can contain uppercase and lowercase letters, numbers,\n hyphens (-), underscores (_), colons (:), periods (.), forward slashes (/), and number signs (#). This parameter maps to <code>Image</code> in the\n   <a href=\"https://docs.docker.com/engine/api/v1.23/#create-a-container\">Create a container</a> section of the <a href=\"https://docs.docker.com/engine/api/v1.23/\">Docker Remote API</a> and the <code>IMAGE</code>\n   parameter of <a href=\"https://docs.docker.com/engine/reference/run/\">docker run</a>.</p>\n         <note>\n            <p>Docker image architecture must match the processor architecture of the compute resources\n    that they're scheduled on. For example, ARM-based Docker images can only run on ARM-based\n    compute resources.</p>\n         </note>\n         <ul>\n            <li>\n               <p>Images in Amazon ECR Public repositories use the full <code>registry/repository[:tag]</code> or\n      <code>registry/repository[@digest]</code> naming conventions. For example,\n       <code>public.ecr.aws/<i>registry_alias</i>/<i>my-web-app</i>:<i>latest</i>\n                  </code>.</p>\n            </li>\n            <li>\n               <p>Images in Amazon ECR repositories use the full registry and repository URI (for example,\n      <code>123456789012.dkr.ecr.<region-name>.amazonaws.com/<repository-name></code>).</p>\n            </li>\n            <li>\n               <p>Images in official repositories on Docker Hub use a single name (for example,\n      <code>ubuntu</code> or <code>mongo</code>).</p>\n            </li>\n            <li>\n               <p>Images in other repositories on Docker Hub are qualified with an organization name (for\n     example, <code>amazon/amazon-ecs-agent</code>).</p>\n            </li>\n            <li>\n               <p>Images in other online repositories are qualified further by a domain name (for example,\n      <code>quay.io/assemblyline/ubuntu</code>).</p>\n            </li>\n         </ul>"}))
    ContainerProperties.add_member(:vcpus, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'vcpus', traits: {"smithy.api#deprecated" => {"message" => "This field is deprecated, use resourceRequirements instead."}, "smithy.api#documentation" => "<p>This parameter is deprecated, use <code>resourceRequirements</code> to specify the vCPU\n   requirements for the job definition. It's not supported for jobs running on Fargate resources.\n   For jobs running on Amazon EC2 resources, it specifies the number of vCPUs reserved for the\n   job.</p>\n         <p>Each vCPU is equivalent to 1,024 CPU shares. This parameter maps to <code>CpuShares</code>\n   in the <a href=\"https://docs.docker.com/engine/api/v1.23/#create-a-container\">Create a container</a> section of the <a href=\"https://docs.docker.com/engine/api/v1.23/\">Docker Remote API</a> and the\n    <code>--cpu-shares</code> option to <a href=\"https://docs.docker.com/engine/reference/run/\">docker run</a>. The\n   number of vCPUs must be specified but can be specified in several places. You must specify it at\n   least once for each node.</p>"}))
    ContainerProperties.add_member(:memory, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'memory', traits: {"smithy.api#deprecated" => {"message" => "This field is deprecated, use resourceRequirements instead."}, "smithy.api#documentation" => "<p>This parameter is deprecated, use <code>resourceRequirements</code> to specify the memory\n   requirements for the job definition. It's not supported for jobs running on Fargate resources.\n   For jobs that run on Amazon EC2 resources, it specifies the memory hard limit (in MiB) for a\n   container. If your container attempts to exceed the specified number, it's terminated. You must\n   specify at least 4 MiB of memory for a job using this parameter. The memory hard limit can be\n   specified in several places. It must be specified for each node at least once.</p>"}))
    ContainerProperties.add_member(:command, Smithy::Schema::Shapes::ShapeRef.new(shape: StringList, location_name: 'command', traits: {"smithy.api#documentation" => "<p>The command that's passed to the container. This parameter maps to <code>Cmd</code> in the\n   <a href=\"https://docs.docker.com/engine/api/v1.23/#create-a-container\">Create a container</a> section of the <a href=\"https://docs.docker.com/engine/api/v1.23/\">Docker Remote API</a> and the <code>COMMAND</code>\n   parameter to <a href=\"https://docs.docker.com/engine/reference/run/\">docker run</a>. For more information, see\n    <a href=\"https://docs.docker.com/engine/reference/builder/#cmd\">https://docs.docker.com/engine/reference/builder/#cmd</a>.</p>"}))
    ContainerProperties.add_member(:job_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'jobRoleArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the IAM role that the container can assume for Amazon Web Services permissions. For more\n   information, see <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/task-iam-roles.html\">IAM roles for tasks</a> in the\n    <i>Amazon Elastic Container Service Developer Guide</i>.</p>"}))
    ContainerProperties.add_member(:execution_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'executionRoleArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the execution role that Batch can assume. For jobs that run on Fargate\n   resources, you must provide an execution role. For more information, see <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/execution-IAM-role.html\">Batch execution IAM role</a>\n   in the <i>Batch User Guide</i>.</p>"}))
    ContainerProperties.add_member(:volumes, Smithy::Schema::Shapes::ShapeRef.new(shape: Volumes, location_name: 'volumes', traits: {"smithy.api#documentation" => "<p>A list of data volumes used in a job.</p>"}))
    ContainerProperties.add_member(:environment, Smithy::Schema::Shapes::ShapeRef.new(shape: EnvironmentVariables, location_name: 'environment', traits: {"smithy.api#documentation" => "<p>The environment variables to pass to a container. This parameter maps to <code>Env</code> in\n   the <a href=\"https://docs.docker.com/engine/api/v1.23/#create-a-container\">Create a container</a> section of the <a href=\"https://docs.docker.com/engine/api/v1.23/\">Docker Remote API</a> and the\n    <code>--env</code> option to <a href=\"https://docs.docker.com/engine/reference/run/\">docker run</a>.</p>\n         <important>\n            <p>We don't recommend using plaintext environment variables for sensitive information, such as\n    credential data.</p>\n         </important>\n         <note>\n            <p>Environment variables cannot start with \"<code>AWS_BATCH</code>\". This naming\n convention is reserved for variables that Batch sets.</p>\n         </note>"}))
    ContainerProperties.add_member(:mount_points, Smithy::Schema::Shapes::ShapeRef.new(shape: MountPoints, location_name: 'mountPoints', traits: {"smithy.api#documentation" => "<p>The mount points for data volumes in your container. This parameter maps to\n    <code>Volumes</code> in the <a href=\"https://docs.docker.com/engine/api/v1.23/#create-a-container\">Create a container</a> section of the <a href=\"https://docs.docker.com/engine/api/v1.23/\">Docker Remote API</a>\n   and the <code>--volume</code> option to <a href=\"https://docs.docker.com/engine/reference/run/\">docker\n   run</a>.</p>"}))
    ContainerProperties.add_member(:readonly_root_filesystem, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'readonlyRootFilesystem', traits: {"smithy.api#documentation" => "<p>When this parameter is true, the container is given read-only access to its root file\n   system. This parameter maps to <code>ReadonlyRootfs</code> in the\n   <a href=\"https://docs.docker.com/engine/api/v1.23/#create-a-container\">Create a container</a> section of the <a href=\"https://docs.docker.com/engine/api/v1.23/\">Docker Remote API</a> and the\n    <code>--read-only</code> option to <code>docker run</code>.</p>"}))
    ContainerProperties.add_member(:privileged, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'privileged', traits: {"smithy.api#documentation" => "<p>When this parameter is true, the container is given elevated permissions on the host\n   container instance (similar to the <code>root</code> user). This parameter maps to\n    <code>Privileged</code> in the <a href=\"https://docs.docker.com/engine/api/v1.23/#create-a-container\">Create a container</a> section of the\n   <a href=\"https://docs.docker.com/engine/api/v1.23/\">Docker Remote API</a> and the <code>--privileged</code> option to <a href=\"https://docs.docker.com/engine/reference/run/\">docker run</a>. The default value is false.</p>\n         <note>\n            <p>This parameter isn't applicable to jobs that are running on Fargate resources and\n    shouldn't be provided, or specified as false.</p>\n         </note>"}))
    ContainerProperties.add_member(:ulimits, Smithy::Schema::Shapes::ShapeRef.new(shape: Ulimits, location_name: 'ulimits', traits: {"smithy.api#documentation" => "<p>A list of <code>ulimits</code> to set in the container. This parameter maps to\n    <code>Ulimits</code> in the <a href=\"https://docs.docker.com/engine/api/v1.23/#create-a-container\">Create a container</a> section of the <a href=\"https://docs.docker.com/engine/api/v1.23/\">Docker Remote API</a>\n   and the <code>--ulimit</code> option to <a href=\"https://docs.docker.com/engine/reference/run/\">docker\n   run</a>.</p>\n         <note>\n            <p>This parameter isn't applicable to jobs that are running on Fargate resources and\n    shouldn't be provided.</p>\n         </note>"}))
    ContainerProperties.add_member(:user, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'user', traits: {"smithy.api#documentation" => "<p>The user name to use inside the container. This parameter maps to <code>User</code> in the\n   <a href=\"https://docs.docker.com/engine/api/v1.23/#create-a-container\">Create a container</a> section of the <a href=\"https://docs.docker.com/engine/api/v1.23/\">Docker Remote API</a> and the <code>--user</code>\n   option to <a href=\"https://docs.docker.com/engine/reference/run/\">docker run</a>.</p>"}))
    ContainerProperties.add_member(:instance_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'instanceType', traits: {"smithy.api#documentation" => "<p>The instance type to use for a multi-node parallel job. All node groups in a multi-node\n   parallel job must use the same instance type.</p>\n         <note>\n            <p>This parameter isn't applicable to single-node container jobs or jobs that run on Fargate\n    resources, and shouldn't be provided.</p>\n         </note>"}))
    ContainerProperties.add_member(:resource_requirements, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceRequirements, location_name: 'resourceRequirements', traits: {"smithy.api#documentation" => "<p>The type and amount of resources to assign to a container. The supported resources include\n    <code>GPU</code>, <code>MEMORY</code>, and <code>VCPU</code>.</p>"}))
    ContainerProperties.add_member(:linux_parameters, Smithy::Schema::Shapes::ShapeRef.new(shape: LinuxParameters, location_name: 'linuxParameters', traits: {"smithy.api#documentation" => "<p>Linux-specific modifications that are applied to the container, such as details for device\n   mappings.</p>"}))
    ContainerProperties.add_member(:log_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: LogConfiguration, location_name: 'logConfiguration', traits: {"smithy.api#documentation" => "<p>The log configuration specification for the container.</p>\n         <p>This parameter maps to <code>LogConfig</code> in the <a href=\"https://docs.docker.com/engine/api/v1.23/#create-a-container\">Create a container</a>\n   section of the <a href=\"https://docs.docker.com/engine/api/v1.23/\">Docker Remote API</a> and the <code>--log-driver</code> option to <a href=\"https://docs.docker.com/engine/reference/run/\">docker run</a>. By default, containers use the same logging\n   driver that the Docker daemon uses. However the container might use a different logging driver\n   than the Docker daemon by specifying a log driver with this parameter in the container\n   definition. To use a different logging driver for a container, the log system must be configured\n   properly on the container instance (or on a different log server for remote logging options). For\n   more information on the options for different supported log drivers, see <a href=\"https://docs.docker.com/engine/admin/logging/overview/\">Configure logging drivers</a>\n   in the Docker documentation.</p>\n         <note>\n            <p>Batch currently supports a subset of the logging drivers available to the Docker daemon\n    (shown in the <a href=\"https://docs.aws.amazon.com/AWSCloudFormation/latest/UserGuide/aws-properties-batch-jobdefinition-containerproperties-logconfiguration.html\">LogConfiguration</a> data type).</p>\n         </note>\n         <p>This parameter requires version 1.18 of the Docker Remote API or greater on your\n container instance. To check the Docker Remote API version on your container instance, log in to your\n container instance and run the following command: <code>sudo docker version | grep \"Server API version\"</code>\n         </p>\n         <note>\n            <p>The Amazon ECS container agent running on a container instance must register the logging drivers\n    available on that instance with the <code>ECS_AVAILABLE_LOGGING_DRIVERS</code> environment\n    variable before containers placed on that instance can use these log configuration options. For\n    more information, see <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/ecs-agent-config.html\">Amazon ECS container agent\n     configuration</a> in the <i>Amazon Elastic Container Service Developer Guide</i>.</p>\n         </note>"}))
    ContainerProperties.add_member(:secrets, Smithy::Schema::Shapes::ShapeRef.new(shape: SecretList, location_name: 'secrets', traits: {"smithy.api#documentation" => "<p>The secrets for the container. For more information, see <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/specifying-sensitive-data.html\">Specifying sensitive data</a> in the\n    <i>Batch User Guide</i>.</p>"}))
    ContainerProperties.add_member(:network_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: NetworkConfiguration, location_name: 'networkConfiguration', traits: {"smithy.api#documentation" => "<p>The network configuration for jobs that are running on Fargate resources. Jobs that are\n   running on Amazon EC2 resources must not specify this parameter.</p>"}))
    ContainerProperties.add_member(:fargate_platform_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: FargatePlatformConfiguration, location_name: 'fargatePlatformConfiguration', traits: {"smithy.api#documentation" => "<p>The platform configuration for jobs that are running on Fargate resources. Jobs that are\n   running on Amazon EC2 resources must not specify this parameter.</p>"}))
    ContainerProperties.add_member(:enable_execute_command, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'enableExecuteCommand', traits: {"smithy.api#documentation" => "<p>Determines whether execute command functionality is turned on for this task. If <code>true</code>, execute\n            command functionality is turned on all the containers in the task.</p>"}))
    ContainerProperties.add_member(:ephemeral_storage, Smithy::Schema::Shapes::ShapeRef.new(shape: EphemeralStorage, location_name: 'ephemeralStorage', traits: {"smithy.api#documentation" => "<p>The amount of ephemeral storage to allocate for the task. This parameter is used to expand\n   the total amount of ephemeral storage available, beyond the default amount, for tasks hosted on\n   Fargate.</p>"}))
    ContainerProperties.add_member(:runtime_platform, Smithy::Schema::Shapes::ShapeRef.new(shape: RuntimePlatform, location_name: 'runtimePlatform', traits: {"smithy.api#documentation" => "<p>An object that represents the compute environment architecture for Batch jobs on\n   Fargate.</p>"}))
    ContainerProperties.add_member(:repository_credentials, Smithy::Schema::Shapes::ShapeRef.new(shape: RepositoryCredentials, location_name: 'repositoryCredentials', traits: {"smithy.api#documentation" => "<p>The private repository authentication credentials to use.</p>"}))
    ContainerProperties.type = Types::ContainerProperties
    ContainerSummary.add_member(:exit_code, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'exitCode', traits: {"smithy.api#documentation" => "<p>The exit code to return upon completion.</p>"}))
    ContainerSummary.add_member(:reason, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'reason', traits: {"smithy.api#documentation" => "<p>A short (255 max characters) human-readable string to provide additional details for a\n   running or stopped container.</p>"}))
    ContainerSummary.type = Types::ContainerSummary
    CreateComputeEnvironmentRequest.add_member(:compute_environment_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'computeEnvironmentName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name for your compute environment. It can be up to 128 characters long. It can contain uppercase and\n lowercase letters, numbers, hyphens (-), and underscores (_).</p>", "smithy.api#required" => {}}))
    CreateComputeEnvironmentRequest.add_member(:type, Smithy::Schema::Shapes::ShapeRef.new(shape: CEType, location_name: 'type', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The type of the compute environment: <code>MANAGED</code> or <code>UNMANAGED</code>. For\n      more information, see <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/compute_environments.html\">Compute Environments</a> in the <i>Batch User Guide</i>.</p>", "smithy.api#required" => {}}))
    CreateComputeEnvironmentRequest.add_member(:state, Smithy::Schema::Shapes::ShapeRef.new(shape: CEState, location_name: 'state', traits: {"smithy.api#documentation" => "<p>The state of the compute environment. If the state is <code>ENABLED</code>, then the\n      compute environment accepts jobs from a queue and can scale out automatically based on\n      queues.</p>\n         <p>If the state is <code>ENABLED</code>, then the Batch scheduler can attempt to place jobs\n      from an associated job queue on the compute resources within the environment. If the compute\n      environment is managed, then it can scale its instances out or in automatically, based on the\n      job queue demand.</p>\n         <p>If the state is <code>DISABLED</code>, then the Batch scheduler doesn't attempt to place\n      jobs within the environment. Jobs in a <code>STARTING</code> or <code>RUNNING</code> state\n      continue to progress normally. Managed compute environments in the <code>DISABLED</code> state\n      don't scale out. </p>\n         <note>\n            <p>Compute environments in a <code>DISABLED</code> state may continue to incur billing\n        charges. To prevent additional charges, turn off and then delete the compute environment.\n        For more information, see <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/compute_environment_parameters.html#compute_environment_state\">State</a> in the <i>Batch User Guide</i>.</p>\n         </note>\n         <p>When an instance is idle, the instance scales down to the <code>minvCpus</code> value.\n      However, the instance size doesn't change. For example, consider a <code>c5.8xlarge</code>\n      instance with a <code>minvCpus</code> value of <code>4</code> and a <code>desiredvCpus</code>\n      value of <code>36</code>. This instance doesn't scale down to a <code>c5.large</code>\n      instance.</p>"}))
    CreateComputeEnvironmentRequest.add_member(:unmanagedv_cpus, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'unmanagedvCpus', traits: {"smithy.api#documentation" => "<p>The maximum number of vCPUs for an unmanaged compute environment. This parameter is only\n      used for fair-share scheduling to reserve vCPU capacity for new share identifiers. If this\n      parameter isn't provided for a fair-share job queue, no vCPU capacity is reserved.</p>\n         <note>\n            <p>This parameter is only supported when the <code>type</code> parameter is set to\n          <code>UNMANAGED</code>.</p>\n         </note>"}))
    CreateComputeEnvironmentRequest.add_member(:compute_resources, Smithy::Schema::Shapes::ShapeRef.new(shape: ComputeResource, location_name: 'computeResources', traits: {"smithy.api#documentation" => "<p>Details about the compute resources managed by the compute environment. This parameter is\n      required for managed compute environments. For more information, see <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/compute_environments.html\">Compute Environments</a>\n      in the <i>Batch User Guide</i>.</p>"}))
    CreateComputeEnvironmentRequest.add_member(:service_role, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'serviceRole', traits: {"smithy.api#documentation" => "<p>The full Amazon Resource Name (ARN) of the IAM role that allows Batch to make calls to other Amazon Web Services\n      services on your behalf. For more information, see <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/service_IAM_role.html\">Batch service IAM role</a> in the\n        <i>Batch User Guide</i>.</p>\n         <important>\n            <p>If your account already created the Batch service-linked role, that role is used by\n        default for your compute environment unless you specify a different role here. If the\n        Batch service-linked role doesn't exist in your account, and no role is specified here,\n        the service attempts to create the Batch service-linked role in your account.</p>\n         </important>\n         <p>If your specified role has a path other than <code>/</code>, then you must specify either\n      the full role ARN (recommended) or prefix the role name with the path. For example, if a\n      role with the name <code>bar</code> has a path of <code>/foo/</code>, specify\n        <code>/foo/bar</code> as the role name. For more information, see <a href=\"https://docs.aws.amazon.com/IAM/latest/UserGuide/reference_identifiers.html#identifiers-friendly-names\">Friendly\n        names and paths</a> in the <i>IAM User Guide</i>.</p>\n         <note>\n            <p>Depending on how you created your Batch service role, its ARN might contain the\n          <code>service-role</code> path prefix. When you only specify the name of the service role,\n        Batch assumes that your ARN doesn't use the <code>service-role</code> path prefix. Because\n        of this, we recommend that you specify the full ARN of your service role when you create\n        compute environments.</p>\n         </note>"}))
    CreateComputeEnvironmentRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagrisTagsMap, location_name: 'tags', traits: {"smithy.api#documentation" => "<p>The tags that you apply to the compute environment to help you categorize and organize\n      your resources. Each tag consists of a key and an optional value. For more information, see\n        <a href=\"https://docs.aws.amazon.com/general/latest/gr/aws_tagging.html\">Tagging Amazon Web Services\n        Resources</a> in <i>Amazon Web Services General Reference</i>.</p>\n         <p>These tags can be updated or removed using the <a href=\"https://docs.aws.amazon.com/batch/latest/APIReference/API_TagResource.html\">TagResource</a> and <a href=\"https://docs.aws.amazon.com/batch/latest/APIReference/API_UntagResource.html\">UntagResource</a> API operations. These tags don't propagate to the underlying compute\n      resources.</p>"}))
    CreateComputeEnvironmentRequest.add_member(:eks_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: EksConfiguration, location_name: 'eksConfiguration', traits: {"smithy.api#documentation" => "<p>The details for the Amazon EKS cluster that supports the compute environment.</p>"}))
    CreateComputeEnvironmentRequest.add_member(:context, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'context', traits: {"smithy.api#documentation" => "<p>Reserved.</p>"}))
    CreateComputeEnvironmentRequest.type = Types::CreateComputeEnvironmentRequest
    CreateComputeEnvironmentResponse.add_member(:compute_environment_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'computeEnvironmentName', traits: {"smithy.api#documentation" => "<p>The name of the compute environment. It can be up to 128 characters long. It can contain uppercase and\n lowercase letters, numbers, hyphens (-), and underscores (_).</p>"}))
    CreateComputeEnvironmentResponse.add_member(:compute_environment_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'computeEnvironmentArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the compute environment.</p>"}))
    CreateComputeEnvironmentResponse.type = Types::CreateComputeEnvironmentResponse
    CreateConsumableResourceRequest.add_member(:consumable_resource_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'consumableResourceName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the consumable resource. Must be unique.</p>", "smithy.api#required" => {}}))
    CreateConsumableResourceRequest.add_member(:total_quantity, Smithy::Schema::Shapes::ShapeRef.new(shape: Long, location_name: 'totalQuantity', traits: {"smithy.api#documentation" => "<p>The total amount of the consumable resource that is available. Must be non-negative.</p>"}))
    CreateConsumableResourceRequest.add_member(:resource_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'resourceType', traits: {"smithy.api#documentation" => "<p>Indicates whether the resource is available to be re-used after a job completes. Can be \n            one of: </p>\n         <ul>\n            <li>\n               <p>\n                  <code>REPLENISHABLE</code> (default)</p>\n            </li>\n            <li>\n               <p>\n                  <code>NON_REPLENISHABLE</code>\n               </p>\n            </li>\n         </ul>"}))
    CreateConsumableResourceRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagrisTagsMap, location_name: 'tags', traits: {"smithy.api#documentation" => "<p>The tags that you apply to the consumable resource to help you categorize and organize your\n            resources. Each tag consists of a key and an optional value. For more information, see <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/using-tags.html\">Tagging your Batch resources</a>.</p>"}))
    CreateConsumableResourceRequest.type = Types::CreateConsumableResourceRequest
    CreateConsumableResourceResponse.add_member(:consumable_resource_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'consumableResourceName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the consumable resource.</p>", "smithy.api#required" => {}}))
    CreateConsumableResourceResponse.add_member(:consumable_resource_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'consumableResourceArn', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the consumable resource.</p>", "smithy.api#required" => {}}))
    CreateConsumableResourceResponse.type = Types::CreateConsumableResourceResponse
    CreateJobQueueRequest.add_member(:job_queue_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'jobQueueName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the job queue. It can be up to 128 letters long. It can contain uppercase and\n      lowercase letters, numbers, hyphens (-), and underscores (_).</p>", "smithy.api#required" => {}}))
    CreateJobQueueRequest.add_member(:state, Smithy::Schema::Shapes::ShapeRef.new(shape: JQState, location_name: 'state', traits: {"smithy.api#documentation" => "<p>The state of the job queue. If the job queue state is <code>ENABLED</code>, it is able to\n      accept jobs. If the job queue state is <code>DISABLED</code>, new jobs can't be added to the\n      queue, but jobs already in the queue can finish.</p>"}))
    CreateJobQueueRequest.add_member(:scheduling_policy_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'schedulingPolicyArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the fair-share scheduling policy. Job queues that don't have a fair-share scheduling policy are scheduled in a first-in, first-out (FIFO) model.  After a job queue has a fair-share scheduling policy, it can be replaced but can't be removed.</p>\n         <p>The format is\n          <code>aws:<i>Partition</i>:batch:<i>Region</i>:<i>Account</i>:scheduling-policy/<i>Name</i>\n            </code>.</p>\n         <p>An example is\n        <code>aws:aws:batch:us-west-2:123456789012:scheduling-policy/MySchedulingPolicy</code>.</p>\n         <p>A job queue without a fair-share scheduling policy is scheduled as a FIFO job queue and can't have a fair-share scheduling policy added. Jobs queues with a fair-share scheduling policy can have a maximum of 500 active share identifiers. When the limit has been reached, submissions of any jobs that add a new share identifier fail.</p>"}))
    CreateJobQueueRequest.add_member(:priority, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'priority', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The priority of the job queue. Job queues with a higher priority (or a higher integer\n      value for the <code>priority</code> parameter) are evaluated first when associated with the\n      same compute environment. Priority is determined in descending order. For example, a job queue\n      with a priority value of <code>10</code> is given scheduling preference over a job queue with\n      a priority value of <code>1</code>. All of the compute environments must be either EC2\n        (<code>EC2</code> or <code>SPOT</code>) or Fargate (<code>FARGATE</code> or\n        <code>FARGATE_SPOT</code>); EC2 and Fargate compute environments can't be mixed.</p>", "smithy.api#required" => {}}))
    CreateJobQueueRequest.add_member(:compute_environment_order, Smithy::Schema::Shapes::ShapeRef.new(shape: ComputeEnvironmentOrders, location_name: 'computeEnvironmentOrder', traits: {"smithy.api#documentation" => "<p>The set of compute environments mapped to a job queue and their order relative to each\n      other. The job scheduler uses this parameter to determine which compute environment runs a\n      specific job. Compute environments must be in the <code>VALID</code> state before you can\n      associate them with a job queue. You can associate up to three compute environments with a job\n      queue. All of the compute environments must be either EC2 (<code>EC2</code> or\n        <code>SPOT</code>) or Fargate (<code>FARGATE</code> or <code>FARGATE_SPOT</code>); EC2 and\n      Fargate compute environments can't be mixed.</p>\n         <note>\n            <p>All compute environments that are associated with a job queue must share the same\n        architecture. Batch doesn't support mixing compute environment architecture types in a\n        single job queue.</p>\n         </note>"}))
    CreateJobQueueRequest.add_member(:service_environment_order, Smithy::Schema::Shapes::ShapeRef.new(shape: ServiceEnvironmentOrders, location_name: 'serviceEnvironmentOrder', traits: {"smithy.api#documentation" => "<p>A list of service environments that this job queue can use to allocate jobs. All serviceEnvironments must have the same type. A job queue can't have both a serviceEnvironmentOrder and a computeEnvironmentOrder field.</p>"}))
    CreateJobQueueRequest.add_member(:job_queue_type, Smithy::Schema::Shapes::ShapeRef.new(shape: JobQueueType, location_name: 'jobQueueType', traits: {"smithy.api#documentation" => "<p>The type of job queue. For service jobs that run on SageMaker Training, this value is <code>SAGEMAKER_TRAINING</code>. For regular container jobs, this value is <code>EKS</code>, <code>ECS</code>, or <code>ECS_FARGATE</code> depending on the compute environment.</p>"}))
    CreateJobQueueRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagrisTagsMap, location_name: 'tags', traits: {"smithy.api#documentation" => "<p>The tags that you apply to the job queue to help you categorize and organize your\n      resources. Each tag consists of a key and an optional value. For more information, see <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/using-tags.html\">Tagging your Batch resources</a>\n      in <i>Batch User Guide</i>.</p>"}))
    CreateJobQueueRequest.add_member(:job_state_time_limit_actions, Smithy::Schema::Shapes::ShapeRef.new(shape: JobStateTimeLimitActions, location_name: 'jobStateTimeLimitActions', traits: {"smithy.api#documentation" => "<p>The set of actions that Batch performs on jobs that remain at the head of the job queue in the specified state longer than specified times. Batch will perform each action after <code>maxTimeSeconds</code> has passed. (<b>Note</b>: The minimum value for maxTimeSeconds is 600 (10 minutes) and its maximum value is 86,400 (24 hours).)</p>"}))
