    EcsTaskDetails.add_member(:ipc_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ipcMode', traits: {"smithy.api#documentation" => "<p>The IPC resource namespace to use for the containers in the task.</p>"}))
    EcsTaskDetails.add_member(:task_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'taskRoleArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the IAM role that the container can assume for Amazon Web Services permissions. For more\n   information, see <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/task-iam-roles.html\">IAM roles for tasks</a> in the\n    <i>Amazon Elastic Container Service Developer Guide</i>.</p>\n         <note>\n            <p>This is object is comparable to <a href=\"https://docs.aws.amazon.com/batch/latest/APIReference/API_ContainerProperties.html\">ContainerProperties:jobRoleArn</a>.</p>\n         </note>"}))
