    EcsTaskDetails.add_member(:network_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: NetworkConfiguration, location_name: 'networkConfiguration', traits: {"smithy.api#documentation" => "<p>The network configuration for jobs that are running on Fargate resources. Jobs that are\n   running on Amazon EC2 resources must not specify this parameter.</p>"}))
