    EcsTaskProperties.add_member(:containers, Smithy::Schema::Shapes::ShapeRef.new(shape: ListTaskContainerProperties, location_name: 'containers', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>This object is a list of containers.</p>", "smithy.api#required" => {}}))
    EcsTaskProperties.add_member(:ephemeral_storage, Smithy::Schema::Shapes::ShapeRef.new(shape: EphemeralStorage, location_name: 'ephemeralStorage', traits: {"smithy.api#documentation" => "<p>The amount of ephemeral storage to allocate for the task. This parameter is used to expand\n   the total amount of ephemeral storage available, beyond the default amount, for tasks hosted on\n   Fargate.</p>"}))
    EcsTaskProperties.add_member(:execution_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'executionRoleArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the execution role that Batch can assume. For jobs that run on Fargate\n   resources, you must provide an execution role. For more information, see <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/execution-IAM-role.html\">Batch execution IAM role</a>\n   in the <i>Batch User Guide</i>.</p>"}))
    EcsTaskProperties.add_member(:platform_version, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'platformVersion', traits: {"smithy.api#documentation" => "<p>The Fargate platform version where the jobs are running. A platform version is specified\n   only for jobs that are running on Fargate resources. If one isn't specified, the\n    <code>LATEST</code> platform version is used by default. This uses a recent, approved version of\n   the Fargate platform for compute resources. For more information, see <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/platform_versions.html\">Fargate\n    platform versions</a> in the <i>Amazon Elastic Container Service Developer Guide</i>.</p>"}))
    EcsTaskProperties.add_member(:ipc_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ipcMode', traits: {"smithy.api#documentation" => "<p>The IPC resource namespace to use for the containers in the task. The valid values are\n    <code>host</code>, <code>task</code>, or <code>none</code>.</p>\n         <p>If <code>host</code> is specified, all containers within the tasks that specified the\n    <code>host</code> IPC mode on the same container instance share the same IPC resources with the\n   host Amazon EC2 instance.</p>\n         <p>If <code>task</code> is specified, all containers within the specified <code>task</code>\n   share the same IPC resources.</p>\n         <p>If <code>none</code> is specified, the IPC resources within the containers of a task are\n   private, and are not shared with other containers in a task or on the container instance. </p>\n         <p>If no value is specified, then the IPC resource namespace sharing depends on the Docker\n   daemon setting on the container instance. For more information, see <a href=\"https://docs.docker.com/engine/reference/run/#ipc-settings---ipc\">IPC settings</a> in\n   the Docker run reference.</p>"}))
    EcsTaskProperties.add_member(:task_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'taskRoleArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) that's associated with the Amazon ECS task.</p>\n         <note>\n            <p>This is object is comparable to <a href=\"https://docs.aws.amazon.com/batch/latest/APIReference/API_ContainerProperties.html\">ContainerProperties:jobRoleArn</a>.</p>\n         </note>"}))
    EcsTaskProperties.add_member(:pid_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'pidMode', traits: {"smithy.api#documentation" => "<p>The process namespace to use for the containers in the task. The valid values are\n    <code>host</code> or <code>task</code>. For example, monitoring sidecars might need\n    <code>pidMode</code> to access information about other containers running in the same\n   task.</p>\n         <p>If <code>host</code> is specified, all containers within the tasks that specified the\n    <code>host</code> PID mode on the same container instance share the process namespace with the\n   host Amazon EC2 instance.</p>\n         <p>If <code>task</code> is specified, all containers within the specified task share the same\n   process namespace.</p>\n         <p>If no value is specified, the default is a private namespace for each container. For more\n   information, see <a href=\"https://docs.docker.com/engine/reference/run/#pid-settings---pid\">PID settings</a> in the Docker run reference.</p>"}))
    EcsTaskProperties.add_member(:network_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: NetworkConfiguration, location_name: 'networkConfiguration', traits: {"smithy.api#documentation" => "<p>The network configuration for jobs that are running on Fargate resources. Jobs that are\n   running on Amazon EC2 resources must not specify this parameter.</p>"}))
    EcsTaskProperties.add_member(:runtime_platform, Smithy::Schema::Shapes::ShapeRef.new(shape: RuntimePlatform, location_name: 'runtimePlatform', traits: {"smithy.api#documentation" => "<p>An object that represents the compute environment architecture for Batch jobs on\n   Fargate.</p>"}))
    EcsTaskProperties.add_member(:volumes, Smithy::Schema::Shapes::ShapeRef.new(shape: Volumes, location_name: 'volumes', traits: {"smithy.api#documentation" => "<p>A list of volumes that are associated with the job.</p>"}))
    EcsTaskProperties.add_member(:enable_execute_command, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'enableExecuteCommand', traits: {"smithy.api#documentation" => "<p>Determines whether execute command functionality is turned on for this task. If <code>true</code>, execute\n            command functionality is turned on all the containers in the task.</p>"}))
