    EksAttemptDetail.add_member(:started_at, Smithy::Schema::Shapes::ShapeRef.new(shape: Long, location_name: 'startedAt', traits: {"smithy.api#documentation" => "<p>The Unix timestamp (in milliseconds) for when the attempt was started (when the attempt\n   transitioned from the <code>STARTING</code> state to the <code>RUNNING</code> state).</p>"}))
    EksAttemptDetail.add_member(:stopped_at, Smithy::Schema::Shapes::ShapeRef.new(shape: Long, location_name: 'stoppedAt', traits: {"smithy.api#documentation" => "<p>The Unix timestamp (in milliseconds) for when the attempt was stopped. This happens when the\n   attempt transitioned from the <code>RUNNING</code> state to a terminal state, such as\n    <code>SUCCEEDED</code> or <code>FAILED</code>.</p>"}))
