    EksConfiguration.add_member(:eks_cluster_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'eksClusterArn', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the Amazon EKS cluster. An example is\n     <code>arn:<i>aws</i>:eks:<i>us-east-1</i>:<i>123456789012</i>:cluster/<i>ClusterForBatch</i>\n            </code>.\n  </p>", "smithy.api#required" => {}}))
    EksConfiguration.add_member(:kubernetes_namespace, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'kubernetesNamespace', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The namespace of the Amazon EKS cluster. Batch manages pods in this namespace. The value\n   can't left empty or null. It must be fewer than 64 characters long, can't be set to\n    <code>default</code>, can't start with \"<code>kube-</code>,\" and must match this regular\n   expression: <code>^[a-z0-9]([-a-z0-9]*[a-z0-9])?$</code>. For more information, see <a href=\"https://kubernetes.io/docs/concepts/overview/working-with-objects/namespaces/\">Namespaces</a> in the Kubernetes documentation.</p>", "smithy.api#required" => {}}))
