    EksContainerDetail.add_member(:exit_code, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'exitCode', traits: {"smithy.api#documentation" => "<p>The exit code returned for the job attempt. A non-zero exit code is considered\n   failed.</p>"}))
