    EksContainerResourceRequirements.add_member(:limits, Smithy::Schema::Shapes::ShapeRef.new(shape: EksLimits, location_name: 'limits', traits: {"smithy.api#documentation" => "<p>The type and quantity of the resources to reserve for the container. The values vary based\n   on the <code>name</code> that's specified. Resources can be requested using either the\n    <code>limits</code> or the <code>requests</code> objects.</p>\n         <dl>\n            <dt>memory</dt>\n            <dd>\n               <p>The memory hard limit (in MiB) for the container, using whole integers, with a \"Mi\"\n      suffix. If your container attempts to exceed the memory specified, the container is\n      terminated. You must specify at least 4 MiB of memory for a job. <code>memory</code> can be\n      specified in <code>limits</code>, <code>requests</code>, or both. If <code>memory</code> is\n      specified in both places, then the value that's specified in <code>limits</code> must be equal\n      to the value that's specified in <code>requests</code>.</p>\n               <note>\n                  <p>To maximize your resource utilization, provide your jobs with as much memory as possible\n       for the specific instance type that you are using. To learn how, see <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/memory-management.html\">Memory management</a> in the\n        <i>Batch User Guide</i>.</p>\n               </note>\n            </dd>\n            <dt>cpu</dt>\n            <dd>\n               <p>The number of CPUs that's reserved for the container. Values must be an even multiple of\n       <code>0.25</code>. <code>cpu</code> can be specified in <code>limits</code>,\n       <code>requests</code>, or both. If <code>cpu</code> is specified in both places, then the\n      value that's specified in <code>limits</code> must be at least as large as the value that's\n      specified in <code>requests</code>.</p>\n            </dd>\n            <dt>nvidia.com/gpu</dt>\n            <dd>\n               <p>The number of GPUs that's reserved for the container. Values must be a whole integer.\n       <code>memory</code> can be specified in <code>limits</code>, <code>requests</code>, or both.\n      If <code>memory</code> is specified in both places, then the value that's specified in\n       <code>limits</code> must be equal to the value that's specified in\n      <code>requests</code>.</p>\n            </dd>\n         </dl>"}))
    EksContainerResourceRequirements.add_member(:requests, Smithy::Schema::Shapes::ShapeRef.new(shape: EksRequests, location_name: 'requests', traits: {"smithy.api#documentation" => "<p>The type and quantity of the resources to request for the container. The values vary based\n   on the <code>name</code> that's specified. Resources can be requested by using either the\n    <code>limits</code> or the <code>requests</code> objects.</p>\n         <dl>\n            <dt>memory</dt>\n            <dd>\n               <p>The memory hard limit (in MiB) for the container, using whole integers, with a \"Mi\"\n      suffix. If your container attempts to exceed the memory specified, the container is\n      terminated. You must specify at least 4 MiB of memory for a job. <code>memory</code> can be\n      specified in <code>limits</code>, <code>requests</code>, or both. If <code>memory</code> is\n      specified in both, then the value that's specified in <code>limits</code> must be equal to the\n      value that's specified in <code>requests</code>.</p>\n               <note>\n                  <p>If you're trying to maximize your resource utilization by providing your jobs as much\n       memory as possible for a particular instance type, see <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/memory-management.html\">Memory management</a> in the\n        <i>Batch User Guide</i>.</p>\n               </note>\n            </dd>\n            <dt>cpu</dt>\n            <dd>\n               <p>The number of CPUs that are reserved for the container. Values must be an even multiple\n      of <code>0.25</code>. <code>cpu</code> can be specified in <code>limits</code>,\n       <code>requests</code>, or both. If <code>cpu</code> is specified in both, then the value\n      that's specified in <code>limits</code> must be at least as large as the value that's\n      specified in <code>requests</code>.</p>\n            </dd>\n            <dt>nvidia.com/gpu</dt>\n            <dd>\n               <p>The number of GPUs that are reserved for the container. Values must be a whole integer.\n       <code>nvidia.com/gpu</code> can be specified in <code>limits</code>, <code>requests</code>,\n      or both. If <code>nvidia.com/gpu</code> is specified in both, then the value that's specified\n      in <code>limits</code> must be equal to the value that's specified in\n      <code>requests</code>.</p>\n            </dd>\n         </dl>"}))
    EksContainerResourceRequirements.type = Types::EksContainerResourceRequirements
    EksContainerSecurityContext.add_member(:run_as_user, Smithy::Schema::Shapes::ShapeRef.new(shape: Long, location_name: 'runAsUser', traits: {"smithy.api#documentation" => "<p>When this parameter is specified, the container is run as the specified user ID\n    (<code>uid</code>). If this parameter isn't specified, the default is the user that's specified\n   in the image metadata. This parameter maps to <code>RunAsUser</code> and <code>MustRanAs</code>\n   policy in the <a href=\"https://kubernetes.io/docs/concepts/security/pod-security-policy/#users-and-groups\">Users\n    and groups pod security policies</a> in the <i>Kubernetes\n   documentation</i>.</p>"}))
    EksContainerSecurityContext.add_member(:run_as_group, Smithy::Schema::Shapes::ShapeRef.new(shape: Long, location_name: 'runAsGroup', traits: {"smithy.api#documentation" => "<p>When this parameter is specified, the container is run as the specified group ID\n    (<code>gid</code>). If this parameter isn't specified, the default is the group that's specified\n   in the image metadata. This parameter maps to <code>RunAsGroup</code> and <code>MustRunAs</code>\n   policy in the <a href=\"https://kubernetes.io/docs/concepts/security/pod-security-policy/#users-and-groups\">Users\n    and groups pod security policies</a> in the <i>Kubernetes\n   documentation</i>.</p>"}))
    EksContainerSecurityContext.add_member(:privileged, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'privileged', traits: {"smithy.api#documentation" => "<p>When this parameter is <code>true</code>, the container is given elevated permissions on the\n   host container instance. The level of permissions are similar to the <code>root</code> user\n   permissions. The default value is <code>false</code>. This parameter maps to\n    <code>privileged</code> policy in the <a href=\"https://kubernetes.io/docs/concepts/security/pod-security-policy/#privileged\">Privileged\n    pod security policies</a> in the <i>Kubernetes documentation</i>.</p>"}))
    EksContainerSecurityContext.add_member(:allow_privilege_escalation, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'allowPrivilegeEscalation', traits: {"smithy.api#documentation" => "<p>Whether or not a container or a Kubernetes pod is allowed to gain more privileges than its parent\n   process. The default value is <code>false</code>.</p>"}))
    EksContainerSecurityContext.add_member(:read_only_root_filesystem, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'readOnlyRootFilesystem', traits: {"smithy.api#documentation" => "<p>When this parameter is <code>true</code>, the container is given read-only access to its\n   root file system. The default value is <code>false</code>. This parameter maps to\n    <code>ReadOnlyRootFilesystem</code> policy in the <a href=\"https://kubernetes.io/docs/concepts/security/pod-security-policy/#volumes-and-file-systems\">Volumes and file systems pod security policies</a> in the <i>Kubernetes\n    documentation</i>.</p>"}))
    EksContainerSecurityContext.add_member(:run_as_non_root, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'runAsNonRoot', traits: {"smithy.api#documentation" => "<p>When this parameter is specified, the container is run as a user with a <code>uid</code>\n   other than 0. If this parameter isn't specified, so such rule is enforced. This parameter maps to\n    <code>RunAsUser</code> and <code>MustRunAsNonRoot</code> policy in the <a href=\"https://kubernetes.io/docs/concepts/security/pod-security-policy/#users-and-groups\">Users\n    and groups pod security policies</a> in the <i>Kubernetes\n   documentation</i>.</p>"}))
    EksContainerSecurityContext.type = Types::EksContainerSecurityContext
    EksContainerVolumeMount.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'name', traits: {"smithy.api#documentation" => "<p>The name the volume mount. This must match the name of one of the volumes in the\n   pod.</p>"}))
    EksContainerVolumeMount.add_member(:mount_path, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'mountPath', traits: {"smithy.api#documentation" => "<p>The path on the container where the volume is mounted.</p>"}))
    EksContainerVolumeMount.add_member(:sub_path, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'subPath', traits: {"smithy.api#documentation" => "<p>A sub-path inside the referenced volume instead of its root.</p>"}))
    EksContainerVolumeMount.add_member(:read_only, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'readOnly', traits: {"smithy.api#documentation" => "<p>If this value is <code>true</code>, the container has read-only access to the volume.\n   Otherwise, the container can write to the volume. The default value is <code>false</code>.</p>"}))
    EksContainerVolumeMount.type = Types::EksContainerVolumeMount
    EksContainerVolumeMounts.member = Smithy::Schema::Shapes::ShapeRef.new(shape: EksContainerVolumeMount)
    EksContainers.member = Smithy::Schema::Shapes::ShapeRef.new(shape: EksContainer)
    EksEmptyDir.add_member(:medium, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'medium', traits: {"smithy.api#documentation" => "<p>The medium to store the volume. The default value is an empty string, which uses the storage\n   of the node.</p>\n         <dl>\n            <dt>\"\"</dt>\n            <dd>\n               <p>\n                  <b>(Default)</b> Use the disk storage of the node.</p>\n            </dd>\n            <dt>\"Memory\"</dt>\n            <dd>\n               <p>Use the <code>tmpfs</code> volume that's backed by the RAM of the node. Contents of the\n      volume are lost when the node reboots, and any storage on the volume counts against the\n      container's memory limit.</p>\n            </dd>\n         </dl>"}))
    EksEmptyDir.add_member(:size_limit, Smithy::Schema::Shapes::ShapeRef.new(shape: Quantity, location_name: 'sizeLimit', traits: {"smithy.api#documentation" => "<p>The maximum size of the volume. By default, there's no maximum size defined.</p>"}))
    EksEmptyDir.type = Types::EksEmptyDir
    EksHostPath.add_member(:path, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'path', traits: {"smithy.api#documentation" => "<p>The path of the file or directory on the host to mount into containers on the pod.</p>"}))
    EksHostPath.type = Types::EksHostPath
    EksLabelsMap.key = Smithy::Schema::Shapes::ShapeRef.new(shape: String)
    EksLabelsMap.value = Smithy::Schema::Shapes::ShapeRef.new(shape: String)
    EksLimits.key = Smithy::Schema::Shapes::ShapeRef.new(shape: String)
    EksLimits.value = Smithy::Schema::Shapes::ShapeRef.new(shape: Quantity)
    EksMetadata.add_member(:labels, Smithy::Schema::Shapes::ShapeRef.new(shape: EksLabelsMap, location_name: 'labels', traits: {"smithy.api#documentation" => "<p>Key-value pairs used to identify, sort, and organize cube resources. Can contain up to 63\n   uppercase letters, lowercase letters, numbers, hyphens (-), and underscores (_). Labels can be\n   added or modified at any time. Each resource can have multiple labels, but each key must be\n   unique for a given object.</p>"}))
    EksMetadata.add_member(:annotations, Smithy::Schema::Shapes::ShapeRef.new(shape: EksAnnotationsMap, location_name: 'annotations', traits: {"smithy.api#documentation" => "<p>Key-value pairs used to attach arbitrary, non-identifying metadata to Kubernetes objects. \n        Valid annotation keys have two segments: an optional prefix and a name, separated by a \n        slash (/). </p>\n         <ul>\n            <li>\n               <p>The prefix is optional and must be 253 characters or less. If specified, the prefix \n                must be a DNS subdomain− a series of DNS labels separated by dots (.), and it must \n                end with a slash (/).</p>\n            </li>\n            <li>\n               <p>The name segment is required and must be 63 characters or less. It can include alphanumeric \n                characters ([a-z0-9A-Z]), dashes (-), underscores (_), and dots (.), but must begin and end \n                with an alphanumeric character.</p>\n            </li>\n         </ul>\n         <note>\n            <p>Annotation values must be 255 characters or less.</p>\n         </note>\n         <p>Annotations can be added or modified at any time. Each resource can have multiple annotations. </p>"}))
    EksMetadata.add_member(:namespace, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'namespace', traits: {"smithy.api#documentation" => "<p>The namespace of the Amazon EKS cluster. In Kubernetes, namespaces provide a mechanism for isolating \n      groups of resources within a single cluster. Names of resources need to be unique within a namespace, \n      but not across namespaces. Batch places Batch Job pods in this namespace. If this field is provided, \n      the value can't be empty or null. It must meet the following requirements:</p>\n         <ul>\n            <li>\n               <p>1-63 characters long</p>\n            </li>\n            <li>\n               <p>Can't be set to default</p>\n            </li>\n            <li>\n               <p>Can't start with <code>kube</code>\n               </p>\n            </li>\n            <li>\n               <p>Must match the following regular expression:\n  <code>^[a-z0-9]([-a-z0-9]*[a-z0-9])?$</code>\n               </p>\n            </li>\n         </ul>\n         <p>\n   For more information, see \n   <a href=\"https://kubernetes.io/docs/concepts/overview/working-with-objects/namespaces/\">Namespaces</a> in the <i>Kubernetes documentation</i>. This namespace can be \n   different from the <code>kubernetesNamespace</code> set in the compute environment's \n   <code>EksConfiguration</code>, but must have identical role-based access control (RBAC) roles as \n   the compute environment's <code>kubernetesNamespace</code>. For multi-node parallel jobs,\n   the same value must be provided across all the node ranges.</p>"}))
    EksMetadata.type = Types::EksMetadata
    EksPersistentVolumeClaim.add_member(:claim_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'claimName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the <code>persistentVolumeClaim</code> bounded to a <code>persistentVolume</code>. \n         For more information, see <a href=\"https://kubernetes.io/docs/concepts/storage/persistent-volumes/#persistentvolumeclaims\">\n         Persistent Volume Claims</a> in the <i>Kubernetes documentation</i>.</p>", "smithy.api#required" => {}}))
    EksPersistentVolumeClaim.add_member(:read_only, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'readOnly', traits: {"smithy.api#documentation" => "<p>An optional boolean value indicating if the mount is read only. Default is false. For more\n         information, see <a href=\"https://kubernetes.io/docs/concepts/storage/volumes/#read-only-mounts\">\n         Read Only Mounts</a> in the <i>Kubernetes documentation</i>.</p>"}))
    EksPersistentVolumeClaim.type = Types::EksPersistentVolumeClaim
    EksPodProperties.add_member(:service_account_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'serviceAccountName', traits: {"smithy.api#documentation" => "<p>The name of the service account that's used to run the pod. For more information, see\n    <a href=\"https://docs.aws.amazon.com/eks/latest/userguide/service-accounts.html\">Kubernetes service\n    accounts</a> and <a href=\"https://docs.aws.amazon.com/eks/latest/userguide/associate-service-account-role.html\">Configure a Kubernetes service account\n    to assume an IAM role</a> in the <i>Amazon EKS User Guide</i> and <a href=\"https://kubernetes.io/docs/tasks/configure-pod-container/configure-service-account/\">Configure service accounts for pods</a> in the <i>Kubernetes\n   documentation</i>.</p>"}))
    EksPodProperties.add_member(:host_network, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'hostNetwork', traits: {"smithy.api#documentation" => "<p>Indicates if the pod uses the hosts' network IP address. The default value is\n    <code>true</code>. Setting this to <code>false</code> enables the Kubernetes pod networking model.\n   Most Batch workloads are egress-only and don't require the overhead of IP allocation for each\n   pod for incoming connections. For more information, see <a href=\"https://kubernetes.io/docs/concepts/security/pod-security-policy/#host-namespaces\">Host\n    namespaces</a> and <a href=\"https://kubernetes.io/docs/concepts/workloads/pods/#pod-networking\">Pod networking</a>\n   in the <i>Kubernetes documentation</i>.</p>"}))
    EksPodProperties.add_member(:dns_policy, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'dnsPolicy', traits: {"smithy.api#documentation" => "<p>The DNS policy for the pod. The default value is <code>ClusterFirst</code>. If the\n    <code>hostNetwork</code> parameter is not specified, the default is\n    <code>ClusterFirstWithHostNet</code>. <code>ClusterFirst</code> indicates that any DNS query\n   that does not match the configured cluster domain suffix is forwarded to the upstream nameserver\n   inherited from the node. For more information, see <a href=\"https://kubernetes.io/docs/concepts/services-networking/dns-pod-service/#pod-s-dns-policy\">Pod's DNS policy</a> in the <i>Kubernetes documentation</i>.</p>\n         <p>Valid values: <code>Default</code> | <code>ClusterFirst</code> |\n    <code>ClusterFirstWithHostNet</code>\n         </p>"}))
    EksPodProperties.add_member(:image_pull_secrets, Smithy::Schema::Shapes::ShapeRef.new(shape: ImagePullSecrets, location_name: 'imagePullSecrets', traits: {"smithy.api#documentation" => "<p>References a Kubernetes secret resource. It holds a list of secrets. These secrets help to gain\n   access to pull an images from a private registry.</p>\n         <p>\n            <code>ImagePullSecret$name</code> is required when this object is used.</p>"}))
    EksPodProperties.add_member(:containers, Smithy::Schema::Shapes::ShapeRef.new(shape: EksContainers, location_name: 'containers', traits: {"smithy.api#documentation" => "<p>The properties of the container that's used on the Amazon EKS pod.</p>\n         <note>\n            <p>This object is limited to 10 elements.</p>\n         </note>"}))
    EksPodProperties.add_member(:init_containers, Smithy::Schema::Shapes::ShapeRef.new(shape: EksContainers, location_name: 'initContainers', traits: {"smithy.api#documentation" => "<p>These containers run before application containers, always runs to completion, and must\n   complete successfully before the next container starts. These containers are registered with the\n   Amazon EKS Connector agent and persists the registration information in the Kubernetes backend data store.\n   For more information, see <a href=\"https://kubernetes.io/docs/concepts/workloads/pods/init-containers/\">Init\n    Containers</a> in the <i>Kubernetes documentation</i>.</p>\n         <note>\n            <p>This object is limited to 10 elements.</p>\n         </note>"}))
    EksPodProperties.add_member(:volumes, Smithy::Schema::Shapes::ShapeRef.new(shape: EksVolumes, location_name: 'volumes', traits: {"smithy.api#documentation" => "<p>Specifies the volumes for a job definition that uses Amazon EKS resources.</p>"}))
    EksPodProperties.add_member(:metadata, Smithy::Schema::Shapes::ShapeRef.new(shape: EksMetadata, location_name: 'metadata', traits: {"smithy.api#documentation" => "<p>Metadata about the Kubernetes pod. For more information, see <a href=\"https://kubernetes.io/docs/concepts/overview/working-with-objects/kubernetes-objects/\">Understanding Kubernetes Objects</a> in the <i>Kubernetes\n   documentation</i>.</p>"}))
    EksPodProperties.add_member(:share_process_namespace, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'shareProcessNamespace', traits: {"smithy.api#documentation" => "<p>Indicates if the processes in a container are shared, or visible, to other containers in the\n   same pod. For more information, see <a href=\"https://kubernetes.io/docs/tasks/configure-pod-container/share-process-namespace/\">Share\n    Process Namespace between Containers in a Pod</a>.</p>"}))
    EksPodProperties.type = Types::EksPodProperties
    EksPodPropertiesDetail.add_member(:service_account_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'serviceAccountName', traits: {"smithy.api#documentation" => "<p>The name of the service account that's used to run the pod. For more information, see\n    <a href=\"https://docs.aws.amazon.com/eks/latest/userguide/service-accounts.html\">Kubernetes service\n    accounts</a> and <a href=\"https://docs.aws.amazon.com/eks/latest/userguide/associate-service-account-role.html\">Configure a Kubernetes service account\n    to assume an IAM role</a> in the <i>Amazon EKS User Guide</i> and <a href=\"https://kubernetes.io/docs/tasks/configure-pod-container/configure-service-account/\">Configure service accounts for pods</a> in the <i>Kubernetes\n   documentation</i>.</p>"}))
    EksPodPropertiesDetail.add_member(:host_network, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'hostNetwork', traits: {"smithy.api#documentation" => "<p>Indicates if the pod uses the hosts' network IP address. The default value is\n    <code>true</code>. Setting this to <code>false</code> enables the Kubernetes pod networking model.\n   Most Batch workloads are egress-only and don't require the overhead of IP allocation for each\n   pod for incoming connections. For more information, see <a href=\"https://kubernetes.io/docs/concepts/security/pod-security-policy/#host-namespaces\">Host\n    namespaces</a> and <a href=\"https://kubernetes.io/docs/concepts/workloads/pods/#pod-networking\">Pod networking</a>\n   in the <i>Kubernetes documentation</i>.</p>"}))
    EksPodPropertiesDetail.add_member(:dns_policy, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'dnsPolicy', traits: {"smithy.api#documentation" => "<p>The DNS policy for the pod. The default value is <code>ClusterFirst</code>. If the\n    <code>hostNetwork</code> parameter is not specified, the default is\n    <code>ClusterFirstWithHostNet</code>. <code>ClusterFirst</code> indicates that any DNS query\n   that does not match the configured cluster domain suffix is forwarded to the upstream nameserver\n   inherited from the node. If no value was specified for <code>dnsPolicy</code> in the <a href=\"https://docs.aws.amazon.com/batch/latest/APIReference/API_RegisterJobDefinition.html\">RegisterJobDefinition</a> API operation, then no value will be returned for\n    <code>dnsPolicy</code> by either of <a href=\"https://docs.aws.amazon.com/batch/latest/APIReference/API_DescribeJobDefinitions.html\">DescribeJobDefinitions</a>\n   or <a href=\"https://docs.aws.amazon.com/batch/latest/APIReference/API_DescribeJobs.html\">DescribeJobs</a> API operations. The pod spec setting will contain either\n    <code>ClusterFirst</code> or <code>ClusterFirstWithHostNet</code>, depending on the value of the\n    <code>hostNetwork</code> parameter. For more information, see <a href=\"https://kubernetes.io/docs/concepts/services-networking/dns-pod-service/#pod-s-dns-policy\">Pod's DNS policy</a> in the <i>Kubernetes documentation</i>.</p>\n         <p>Valid values: <code>Default</code> | <code>ClusterFirst</code> |\n    <code>ClusterFirstWithHostNet</code>\n         </p>"}))
    EksPodPropertiesDetail.add_member(:image_pull_secrets, Smithy::Schema::Shapes::ShapeRef.new(shape: ImagePullSecrets, location_name: 'imagePullSecrets', traits: {"smithy.api#documentation" => "<p>Displays the reference pointer to the Kubernetes secret resource. These secrets help to gain\n   access to pull an images from a private registry.</p>"}))
    EksPodPropertiesDetail.add_member(:containers, Smithy::Schema::Shapes::ShapeRef.new(shape: EksContainerDetails, location_name: 'containers', traits: {"smithy.api#documentation" => "<p>The properties of the container that's used on the Amazon EKS pod.</p>"}))
    EksPodPropertiesDetail.add_member(:init_containers, Smithy::Schema::Shapes::ShapeRef.new(shape: EksContainerDetails, location_name: 'initContainers', traits: {"smithy.api#documentation" => "<p>The container registered with the Amazon EKS Connector agent and persists the registration\n   information in the Kubernetes backend data store.</p>"}))
    EksPodPropertiesDetail.add_member(:volumes, Smithy::Schema::Shapes::ShapeRef.new(shape: EksVolumes, location_name: 'volumes', traits: {"smithy.api#documentation" => "<p>Specifies the volumes for a job definition using Amazon EKS resources.</p>"}))
    EksPodPropertiesDetail.add_member(:pod_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'podName', traits: {"smithy.api#documentation" => "<p>The name of the pod for this job.</p>"}))
    EksPodPropertiesDetail.add_member(:node_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'nodeName', traits: {"smithy.api#documentation" => "<p>The name of the node for this job.</p>"}))
    EksPodPropertiesDetail.add_member(:metadata, Smithy::Schema::Shapes::ShapeRef.new(shape: EksMetadata, location_name: 'metadata', traits: {"smithy.api#documentation" => "<p>Describes and uniquely identifies Kubernetes resources. For example, the compute environment that\n   a pod runs in or the <code>jobID</code> for a job running in the pod. For more information, see\n    <a href=\"https://kubernetes.io/docs/concepts/overview/working-with-objects/kubernetes-objects/\">Understanding Kubernetes Objects</a> in the <i>Kubernetes documentation</i>.</p>"}))
    EksPodPropertiesDetail.add_member(:share_process_namespace, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'shareProcessNamespace', traits: {"smithy.api#documentation" => "<p>Indicates if the processes in a container are shared, or visible, to other containers in the\n   same pod. For more information, see <a href=\"https://kubernetes.io/docs/tasks/configure-pod-container/share-process-namespace/\">Share\n    Process Namespace between Containers in a Pod</a>.</p>"}))
    EksPodPropertiesDetail.type = Types::EksPodPropertiesDetail
