    JobQueueDetail.add_member(:priority, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'priority', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The priority of the job queue. Job queue priority determines the order \n   that job queues are evaluated when multiple queues dispatch jobs within a \n   shared compute environment. A higher value for <code>priority</code> indicates\n   a higher priority. Queues are evaluated in cycles, in descending order by\n   priority. For example, a job queue with a priority value of <code>10</code> is \n   evaluated before a queue with a priority value of <code>1</code>. All of the \n   compute environments must be either Amazon EC2 (<code>EC2</code> or <code>SPOT</code>)\n   or Fargate (<code>FARGATE</code> or <code>FARGATE_SPOT</code>). Amazon EC2 and \n   Fargate compute environments can't be mixed.</p>\n         <note>\n            <p>Job queue priority doesn't guarantee that a particular job executes before \n    a job in a lower priority queue. Jobs added to higher priority queues during the \n    queue evaluation cycle might not be evaluated until the next cycle. A job is \n    dispatched from a queue only if resources are available when the queue is evaluated. \n    If there are insufficient resources available at that time, the cycle proceeds to the \n    next queue. This means that jobs added to higher priority queues might have to wait \n    for jobs in multiple lower priority queues to complete before they are dispatched. \n    You can use job dependencies to control the order for jobs from queues with different \n    priorities. For more information, see <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/job_dependencies.html\">Job Dependencies</a>\n    in the <i>Batch User Guide</i>.</p>\n         </note>", "smithy.api#required" => {}}))
    JobQueueDetail.add_member(:compute_environment_order, Smithy::Schema::Shapes::ShapeRef.new(shape: ComputeEnvironmentOrders, location_name: 'computeEnvironmentOrder', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The compute environments that are attached to the job queue and the order that job placement\n   is preferred. Compute environments are selected for job placement in ascending order.</p>", "smithy.api#required" => {}}))
    JobQueueDetail.add_member(:service_environment_order, Smithy::Schema::Shapes::ShapeRef.new(shape: ServiceEnvironmentOrders, location_name: 'serviceEnvironmentOrder', traits: {"smithy.api#documentation" => "<p>The order of the service environment associated with the job queue. Job queues with a higher priority are evaluated first when associated with the same service environment.</p>"}))
    JobQueueDetail.add_member(:job_queue_type, Smithy::Schema::Shapes::ShapeRef.new(shape: JobQueueType, location_name: 'jobQueueType', traits: {"smithy.api#documentation" => "<p>The type of job queue. For service jobs that run on SageMaker Training, this value is <code>SAGEMAKER_TRAINING</code>. For regular container jobs, this value is <code>EKS</code>, <code>ECS</code>, or <code>ECS_FARGATE</code> depending on the compute environment.</p>"}))
    JobQueueDetail.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagrisTagsMap, location_name: 'tags', traits: {"smithy.api#documentation" => "<p>The tags that are applied to the job queue. For more information, see <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/using-tags.html\">Tagging your Batch resources</a> in\n    <i>Batch User Guide</i>.</p>"}))
