    JobStateTimeLimitAction.add_member(:state, Smithy::Schema::Shapes::ShapeRef.new(shape: JobStateTimeLimitActionsState, location_name: 'state', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The state of the job needed to trigger the action. The only supported value is <code>RUNNABLE</code>.</p>", "smithy.api#required" => {}}))
