    ListJobsByConsumableResourceSummary.add_member(:job_status, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'jobStatus', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The status of the job. Can be one of:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>SUBMITTED</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>PENDING</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>RUNNABLE</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>STARTING</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>RUNNING</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>SUCCEEDED</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>FAILED</code>\n               </p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
