    NodePropertiesSummary.add_member(:num_nodes, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'numNodes', traits: {"smithy.api#documentation" => "<p>The number of nodes that are associated with a multi-node parallel job.</p>"}))
    NodePropertiesSummary.add_member(:node_index, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'nodeIndex', traits: {"smithy.api#documentation" => "<p>The node index for the node. Node index numbering begins at zero. This index is also\n   available on the node with the <code>AWS_BATCH_JOB_NODE_INDEX</code> environment variable.</p>"}))
    NodePropertiesSummary.type = Types::NodePropertiesSummary
    NodePropertyOverride.add_member(:target_nodes, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'targetNodes', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The range of nodes, using node index values, that's used to override. A range of\n    <code>0:3</code> indicates nodes with index values of <code>0</code> through <code>3</code>. If\n   the starting range value is omitted (<code>:n</code>), then <code>0</code> is used to start the\n   range. If the ending range value is omitted (<code>n:</code>), then the highest possible node\n   index is used to end the range.</p>", "smithy.api#required" => {}}))
    NodePropertyOverride.add_member(:container_overrides, Smithy::Schema::Shapes::ShapeRef.new(shape: ContainerOverrides, location_name: 'containerOverrides', traits: {"smithy.api#documentation" => "<p>The overrides that are sent to a node range.</p>"}))
    NodePropertyOverride.add_member(:ecs_properties_override, Smithy::Schema::Shapes::ShapeRef.new(shape: EcsPropertiesOverride, location_name: 'ecsPropertiesOverride', traits: {"smithy.api#documentation" => "<p>An object that contains the properties that you want to replace for the existing Amazon ECS\n   resources of a job.</p>"}))
