    NodePropertyOverride.add_member(:eks_properties_override, Smithy::Schema::Shapes::ShapeRef.new(shape: EksPropertiesOverride, location_name: 'eksPropertiesOverride', traits: {"smithy.api#documentation" => "<p>An object that contains the properties that you want to replace for the existing Amazon EKS resources of a job.</p>"}))
