    RegisterJobDefinitionRequest.add_member(:job_definition_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'jobDefinitionName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the job definition to register. It can be up to 128 letters long. It can\n      contain uppercase and lowercase letters, numbers, hyphens (-), and underscores (_).</p>", "smithy.api#required" => {}}))
    RegisterJobDefinitionRequest.add_member(:type, Smithy::Schema::Shapes::ShapeRef.new(shape: JobDefinitionType, location_name: 'type', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The type of job definition. For more information about multi-node parallel jobs, see\n        <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/multi-node-job-def.html\">Creating a multi-node\n        parallel job definition</a> in the <i>Batch User Guide</i>.</p>\n         <ul>\n            <li>\n               <p>If the value is <code>container</code>, then one of the following is required: <code>containerProperties</code>, <code>ecsProperties</code>, or <code>eksProperties</code>.</p>\n            </li>\n            <li>\n               <p>If the value is <code>multinode</code>, then <code>nodeProperties</code> is required.</p>\n            </li>\n         </ul>\n         <note>\n            <p>If the job is run on Fargate resources, then <code>multinode</code> isn't supported.</p>\n         </note>", "smithy.api#required" => {}}))
    RegisterJobDefinitionRequest.add_member(:parameters, Smithy::Schema::Shapes::ShapeRef.new(shape: ParametersMap, location_name: 'parameters', traits: {"smithy.api#documentation" => "<p>Default parameter substitution placeholders to set in the job definition. Parameters are\n      specified as a key-value pair mapping. Parameters in a <code>SubmitJob</code> request override\n      any corresponding parameter defaults from the job definition.</p>"}))
    RegisterJobDefinitionRequest.add_member(:scheduling_priority, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'schedulingPriority', traits: {"smithy.api#documentation" => "<p>The scheduling priority for jobs that are submitted with this job definition. This only\n      affects jobs in job queues with a fair-share policy. Jobs with a higher scheduling priority\n      are scheduled before jobs with a lower scheduling priority.</p>\n         <p>The minimum supported value is 0 and the maximum supported value is 9999.</p>"}))
    RegisterJobDefinitionRequest.add_member(:container_properties, Smithy::Schema::Shapes::ShapeRef.new(shape: ContainerProperties, location_name: 'containerProperties', traits: {"smithy.api#documentation" => "<p>An object with properties specific to Amazon ECS-based single-node container-based jobs. If the\n      job definition's <code>type</code> parameter is <code>container</code>, then you must specify\n      either <code>containerProperties</code> or <code>nodeProperties</code>. This must not be\n      specified for Amazon EKS-based job definitions.</p>\n         <note>\n            <p>If the job runs on Fargate resources, then you must not specify\n          <code>nodeProperties</code>; use only <code>containerProperties</code>.</p>\n         </note>"}))
    RegisterJobDefinitionRequest.add_member(:node_properties, Smithy::Schema::Shapes::ShapeRef.new(shape: NodeProperties, location_name: 'nodeProperties', traits: {"smithy.api#documentation" => "<p>An object with properties specific to multi-node parallel jobs. If you specify node\n      properties for a job, it becomes a multi-node parallel job. For more information, see <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/multi-node-parallel-jobs.html\">Multi-node Parallel\n        Jobs</a> in the <i>Batch User Guide</i>.</p>\n         <note>\n            <p>If the job runs on Fargate resources, then you must not specify\n          <code>nodeProperties</code>; use <code>containerProperties</code> instead.</p>\n         </note>\n         <note>\n            <p>If the job runs on Amazon EKS resources, then you must not specify\n          <code>nodeProperties</code>.</p>\n         </note>"}))
    RegisterJobDefinitionRequest.add_member(:retry_strategy, Smithy::Schema::Shapes::ShapeRef.new(shape: RetryStrategy, location_name: 'retryStrategy', traits: {"smithy.api#documentation" => "<p>The retry strategy to use for failed jobs that are submitted with this job definition. Any\n      retry strategy that's specified during a <a>SubmitJob</a> operation overrides the\n      retry strategy defined here. If a job is terminated due to a timeout, it isn't retried.</p>"}))
    RegisterJobDefinitionRequest.add_member(:propagate_tags, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'propagateTags', traits: {"smithy.api#documentation" => "<p>Specifies whether to propagate the tags from the job or job definition to the\n      corresponding Amazon ECS task. If no value is specified, the tags are not propagated. Tags can only\n      be propagated to the tasks during task creation. For tags with the same name, job tags are\n      given priority over job definitions tags. If the total number of combined tags from the job\n      and job definition is over 50, the job is moved to the <code>FAILED</code> state.</p>\n         <note>\n            <p>If the job runs on Amazon EKS resources, then you must not specify\n        <code>propagateTags</code>.</p>\n         </note>"}))
    RegisterJobDefinitionRequest.add_member(:timeout, Smithy::Schema::Shapes::ShapeRef.new(shape: JobTimeout, location_name: 'timeout', traits: {"smithy.api#documentation" => "<p>The timeout configuration for jobs that are submitted with this job definition, after\n      which Batch terminates your jobs if they have not finished. If a job is terminated due to a\n      timeout, it isn't retried. The minimum value for the timeout is 60 seconds. Any timeout\n      configuration that's specified during a <a>SubmitJob</a> operation overrides the\n      timeout configuration defined here. For more information, see <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/job_timeouts.html\">Job Timeouts</a> in the\n        <i>Batch User Guide</i>.</p>"}))
    RegisterJobDefinitionRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagrisTagsMap, location_name: 'tags', traits: {"smithy.api#documentation" => "<p>The tags that you apply to the job definition to help you categorize and organize your\n      resources. Each tag consists of a key and an optional value. For more information, see <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/using-tags.html\">Tagging Amazon Web Services Resources</a> in\n        <i>Batch User Guide</i>.</p>"}))
    RegisterJobDefinitionRequest.add_member(:platform_capabilities, Smithy::Schema::Shapes::ShapeRef.new(shape: PlatformCapabilityList, location_name: 'platformCapabilities', traits: {"smithy.api#documentation" => "<p>The platform capabilities required by the job definition. If no value is specified, it\n      defaults to <code>EC2</code>. To run the job on Fargate resources, specify\n        <code>FARGATE</code>.</p>\n         <note>\n            <p>If the job runs on Amazon EKS resources, then you must not specify\n          <code>platformCapabilities</code>.</p>\n         </note>"}))
    RegisterJobDefinitionRequest.add_member(:eks_properties, Smithy::Schema::Shapes::ShapeRef.new(shape: EksProperties, location_name: 'eksProperties', traits: {"smithy.api#documentation" => "<p>An object with properties that are specific to Amazon EKS-based jobs. This must not be\n      specified for Amazon ECS based job definitions.</p>"}))
    RegisterJobDefinitionRequest.add_member(:ecs_properties, Smithy::Schema::Shapes::ShapeRef.new(shape: EcsProperties, location_name: 'ecsProperties', traits: {"smithy.api#documentation" => "<p>An object with properties that are specific to Amazon ECS-based jobs. This must not be\n      specified for Amazon EKS-based job definitions.</p>"}))
    RegisterJobDefinitionRequest.add_member(:consumable_resource_properties, Smithy::Schema::Shapes::ShapeRef.new(shape: ConsumableResourceProperties, location_name: 'consumableResourceProperties', traits: {"smithy.api#documentation" => "<p>Contains a list of consumable resources required by the job.</p>"}))
