    RegisterJobDefinitionResponse.add_member(:job_definition_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'jobDefinitionArn', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the job definition.</p>", "smithy.api#required" => {}}))
