    SubmitJobRequest.add_member(:share_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'shareIdentifier', traits: {"smithy.api#documentation" => "<p>The share identifier for the job. Don't specify this parameter if the job queue doesn't\n      have a fair-share scheduling policy. If the job queue has a fair-share scheduling policy, then this parameter must\n      be specified.</p>\n         <p>This string is limited to 255 alphanumeric characters, and can be followed by an asterisk\n      (*).</p>"}))
    SubmitJobRequest.add_member(:scheduling_priority_override, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'schedulingPriorityOverride', traits: {"smithy.api#documentation" => "<p>The scheduling priority for the job. This only affects jobs in job queues with a \n      fair-share policy. Jobs with a higher scheduling priority are scheduled before jobs with a lower\n      scheduling priority. This overrides any scheduling priority in the job definition and works only \n      within a single share identifier.</p>\n         <p>The minimum supported value is 0 and the maximum supported value is 9999.</p>"}))
    SubmitJobRequest.add_member(:array_properties, Smithy::Schema::Shapes::ShapeRef.new(shape: ArrayProperties, location_name: 'arrayProperties', traits: {"smithy.api#documentation" => "<p>The array properties for the submitted job, such as the size of the array. The array size\n      can be between 2 and 10,000. If you specify array properties for a job, it becomes an array\n      job. For more information, see <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/array_jobs.html\">Array Jobs</a> in the <i>Batch User Guide</i>.</p>"}))
    SubmitJobRequest.add_member(:depends_on, Smithy::Schema::Shapes::ShapeRef.new(shape: JobDependencyList, location_name: 'dependsOn', traits: {"smithy.api#documentation" => "<p>A list of dependencies for the job. A job can depend upon a maximum of 20 jobs. You can\n      specify a <code>SEQUENTIAL</code> type dependency without specifying a job ID for array jobs\n      so that each child array job completes sequentially, starting at index 0. You can also specify\n      an <code>N_TO_N</code> type dependency with a job ID for array jobs. In that case, each index\n      child of this job must wait for the corresponding index child of each dependency to complete\n      before it can begin.</p>"}))
    SubmitJobRequest.add_member(:job_definition, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'jobDefinition', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The job definition used by this job. This value can be one of\n      <code>definition-name</code>, <code>definition-name:revision</code>, or the Amazon Resource Name (ARN) for the\n      job definition, with or without the revision\n          (<code>arn:aws:batch:<i>region</i>:<i>account</i>:job-definition/<i>definition-name</i>:<i>revision</i>\n            </code>,\n      or\n          <code>arn:aws:batch:<i>region</i>:<i>account</i>:job-definition/<i>definition-name</i>\n            </code>).</p>\n         <p>If the revision is not specified, then the latest active revision is used.</p>", "smithy.api#required" => {}}))
    SubmitJobRequest.add_member(:parameters, Smithy::Schema::Shapes::ShapeRef.new(shape: ParametersMap, location_name: 'parameters', traits: {"smithy.api#documentation" => "<p>Additional parameters passed to the job that replace parameter substitution placeholders\n      that are set in the job definition. Parameters are specified as a key and value pair mapping.\n      Parameters in a <code>SubmitJob</code> request override any corresponding parameter defaults\n      from the job definition.</p>"}))
    SubmitJobRequest.add_member(:container_overrides, Smithy::Schema::Shapes::ShapeRef.new(shape: ContainerOverrides, location_name: 'containerOverrides', traits: {"smithy.api#documentation" => "<p>An object with properties that override the defaults for the job definition that specify\n      the name of a container in the specified job definition and the overrides it should receive.\n      You can override the default command for a container, which is specified in the job definition\n      or the Docker image, with a <code>command</code> override. You can also override existing\n      environment variables on a container or add new environment variables to it with an\n        <code>environment</code> override.</p>"}))
    SubmitJobRequest.add_member(:node_overrides, Smithy::Schema::Shapes::ShapeRef.new(shape: NodeOverrides, location_name: 'nodeOverrides', traits: {"smithy.api#documentation" => "<p>A list of node overrides in JSON format that specify the node range to target and the\n      container overrides for that node range.</p>\n         <note>\n            <p>This parameter isn't applicable to jobs that are running on Fargate resources; use\n          <code>containerOverrides</code> instead.</p>\n         </note>"}))
    SubmitJobRequest.add_member(:retry_strategy, Smithy::Schema::Shapes::ShapeRef.new(shape: RetryStrategy, location_name: 'retryStrategy', traits: {"smithy.api#documentation" => "<p>The retry strategy to use for failed jobs from this <a>SubmitJob</a> operation.\n      When a retry strategy is specified here, it overrides the retry strategy defined in the job\n      definition.</p>"}))
    SubmitJobRequest.add_member(:propagate_tags, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'propagateTags', traits: {"smithy.api#documentation" => "<p>Specifies whether to propagate the tags from the job or job definition to the\n      corresponding Amazon ECS task. If no value is specified, the tags aren't propagated. Tags can only\n      be propagated to the tasks during task creation. For tags with the same name, job tags are\n      given priority over job definitions tags. If the total number of combined tags from the job\n      and job definition is over 50, the job is moved to the <code>FAILED</code> state. When\n      specified, this overrides the tag propagation setting in the job definition.</p>"}))
    SubmitJobRequest.add_member(:timeout, Smithy::Schema::Shapes::ShapeRef.new(shape: JobTimeout, location_name: 'timeout', traits: {"smithy.api#documentation" => "<p>The timeout configuration for this <a>SubmitJob</a> operation. You can specify\n      a timeout duration after which Batch terminates your jobs if they haven't finished. If a job\n      is terminated due to a timeout, it isn't retried. The minimum value for the timeout is 60\n      seconds. This configuration overrides any timeout configuration specified in the job\n      definition. For array jobs, child jobs have the same timeout configuration as the parent job.\n      For more information, see <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/job_timeouts.html\">Job Timeouts</a> in the\n        <i>Amazon Elastic Container Service Developer Guide</i>.</p>"}))
    SubmitJobRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagrisTagsMap, location_name: 'tags', traits: {"smithy.api#documentation" => "<p>The tags that you apply to the job request to help you categorize and organize your\n      resources. Each tag consists of a key and an optional value. For more information, see <a href=\"https://docs.aws.amazon.com/general/latest/gr/aws_tagging.html\">Tagging Amazon Web Services\n        Resources</a> in <i>Amazon Web Services General Reference</i>.</p>"}))
    SubmitJobRequest.add_member(:eks_properties_override, Smithy::Schema::Shapes::ShapeRef.new(shape: EksPropertiesOverride, location_name: 'eksPropertiesOverride', traits: {"smithy.api#documentation" => "<p>An object, with properties that override defaults for the job definition, can only be specified for jobs that are run on Amazon EKS resources.</p>"}))
    SubmitJobRequest.add_member(:ecs_properties_override, Smithy::Schema::Shapes::ShapeRef.new(shape: EcsPropertiesOverride, location_name: 'ecsPropertiesOverride', traits: {"smithy.api#documentation" => "<p>An object, with properties that override defaults for the job definition, can only be specified for jobs that are run on Amazon ECS resources.</p>"}))
    SubmitJobRequest.add_member(:consumable_resource_properties_override, Smithy::Schema::Shapes::ShapeRef.new(shape: ConsumableResourceProperties, location_name: 'consumableResourcePropertiesOverride', traits: {"smithy.api#documentation" => "<p>An object that contains overrides for the consumable resources of a job.</p>"}))
    SubmitJobRequest.type = Types::SubmitJobRequest
    SubmitJobResponse.add_member(:job_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'jobArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) for the job.</p>"}))
    SubmitJobResponse.add_member(:job_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'jobName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the job.</p>", "smithy.api#required" => {}}))
    SubmitJobResponse.add_member(:job_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'jobId', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The unique identifier for the job.</p>", "smithy.api#required" => {}}))
    SubmitJobResponse.type = Types::SubmitJobResponse
    SubmitServiceJobRequest.add_member(:job_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'jobName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the service job. It can be up to 128 characters long. It can contain uppercase and lowercase letters, numbers, hyphens (-), and underscores (_).</p>", "smithy.api#required" => {}}))
    SubmitServiceJobRequest.add_member(:job_queue, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'jobQueue', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The job queue into which the service job is submitted. You can specify either the name or the ARN of the queue. The job queue must have the type <code>SAGEMAKER_TRAINING</code>.</p>", "smithy.api#required" => {}}))
    SubmitServiceJobRequest.add_member(:retry_strategy, Smithy::Schema::Shapes::ShapeRef.new(shape: ServiceJobRetryStrategy, location_name: 'retryStrategy', traits: {"smithy.api#documentation" => "<p>The retry strategy to use for failed service jobs that are submitted with this service job request. </p>"}))
    SubmitServiceJobRequest.add_member(:scheduling_priority, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'schedulingPriority', traits: {"smithy.api#documentation" => "<p>The scheduling priority of the service job.  Valid values are integers between 0 and 9999.</p>"}))
    SubmitServiceJobRequest.add_member(:service_request_payload, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'serviceRequestPayload', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The request, in JSON, for the service that the SubmitServiceJob operation is queueing. </p>", "smithy.api#required" => {}}))
    SubmitServiceJobRequest.add_member(:service_job_type, Smithy::Schema::Shapes::ShapeRef.new(shape: ServiceJobType, location_name: 'serviceJobType', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The type of service job. For SageMaker Training jobs, specify <code>SAGEMAKER_TRAINING</code>.</p>", "smithy.api#required" => {}}))
    SubmitServiceJobRequest.add_member(:share_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'shareIdentifier', traits: {"smithy.api#documentation" => "<p>The share identifier for the service job. Don't specify this parameter if the job queue doesn't have a fair-\n           share scheduling policy. If the job queue has a fair-share scheduling policy, then this parameter\n           must be specified.</p>"}))
    SubmitServiceJobRequest.add_member(:timeout_config, Smithy::Schema::Shapes::ShapeRef.new(shape: ServiceJobTimeout, location_name: 'timeoutConfig', traits: {"smithy.api#documentation" => "<p>The timeout configuration for the service job. If none is specified, Batch defers to the default timeout of the underlying service handling the job.</p>"}))
    SubmitServiceJobRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagrisTagsMap, location_name: 'tags', traits: {"smithy.api#documentation" => "<p>The tags that you apply to the service job request. Each tag consists of a key and an optional value. For more information, see <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/using-tags.html\">Tagging your Batch resources</a>.</p>"}))
    SubmitServiceJobRequest.add_member(:client_token, Smithy::Schema::Shapes::ShapeRef.new(shape: ClientRequestToken, location_name: 'clientToken', traits: {"smithy.api#documentation" => "<p>A unique identifier for the request. This token is used to ensure idempotency of requests. If this parameter is specified and two submit requests with identical payloads and <code>clientToken</code>s are received, these requests are considered the same request and the second request is rejected.</p>", "smithy.api#idempotencyToken" => {}}))
    SubmitServiceJobRequest.type = Types::SubmitServiceJobRequest
    SubmitServiceJobResponse.add_member(:job_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'jobArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) for the service job.</p>"}))
    SubmitServiceJobResponse.add_member(:job_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'jobName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the service job.</p>", "smithy.api#required" => {}}))
    SubmitServiceJobResponse.add_member(:job_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'jobId', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The unique identifier for the service job.</p>", "smithy.api#required" => {}}))
    SubmitServiceJobResponse.type = Types::SubmitServiceJobResponse
    TagKeysList.member = Smithy::Schema::Shapes::ShapeRef.new(shape: TagKey)
    TagResourceRequest.add_member(:resource_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'resourceArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the resource that tags are added to. Batch resources that support tags are compute environments, jobs, job definitions, job queues,\n and scheduling policies. ARNs for child jobs of array and multi-node parallel (MNP) jobs aren't supported.</p>", "smithy.api#httpLabel" => {}, "smithy.api#required" => {}}))
    TagResourceRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagrisTagsMap, location_name: 'tags', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The tags that you apply to the resource to help you categorize and organize your\n      resources. Each tag consists of a key and an optional value. For more information, see <a href=\"https://docs.aws.amazon.com/general/latest/gr/aws_tagging.html\">Tagging Amazon Web Services\n        Resources</a> in <i>Amazon Web Services General Reference</i>.</p>", "smithy.api#required" => {}}))
    TagResourceRequest.type = Types::TagResourceRequest
    TagResourceResponse.type = Types::TagResourceResponse
    TagrisTagsMap.key = Smithy::Schema::Shapes::ShapeRef.new(shape: TagKey)
    TagrisTagsMap.value = Smithy::Schema::Shapes::ShapeRef.new(shape: TagValue)
    TagsMap.key = Smithy::Schema::Shapes::ShapeRef.new(shape: String)
    TagsMap.value = Smithy::Schema::Shapes::ShapeRef.new(shape: String)
    TaskContainerDependency.add_member(:container_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'containerName', traits: {"smithy.api#documentation" => "<p>A unique identifier for the container.</p>"}))
    TaskContainerDependency.add_member(:condition, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'condition', traits: {"smithy.api#documentation" => "<p>The dependency condition of the container. The following are the available conditions and\n   their behavior:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>START</code> - This condition emulates the behavior of links and volumes today. It\n     validates that a dependent container is started before permitting other containers to start.\n    </p>\n            </li>\n            <li>\n               <p>\n                  <code>COMPLETE</code> - This condition validates that a dependent container runs to\n     completion (exits) before permitting other containers to start. This can be useful for\n     nonessential containers that run a script and then exit. This condition can't be set on an\n     essential container. </p>\n            </li>\n            <li>\n               <p>\n                  <code>SUCCESS</code> - This condition is the same as <code>COMPLETE</code>, but it also\n     requires that the container exits with a zero status. This condition can't be set on an\n     essential container. </p>\n            </li>\n         </ul>"}))
    TaskContainerDependency.type = Types::TaskContainerDependency
    TaskContainerDependencyList.member = Smithy::Schema::Shapes::ShapeRef.new(shape: TaskContainerDependency)
    TaskContainerDetails.add_member(:command, Smithy::Schema::Shapes::ShapeRef.new(shape: StringList, location_name: 'command', traits: {"smithy.api#documentation" => "<p>The command that's passed to the container. This parameter maps to <code>Cmd</code> in the\n   <a href=\"https://docs.docker.com/engine/api/v1.23/#create-a-container\">Create a container</a> section of the <a href=\"https://docs.docker.com/engine/api/v1.23/\">Docker Remote API</a> and the <code>COMMAND</code>\n   parameter to <a href=\"https://docs.docker.com/engine/reference/run/\">docker run</a>. For more information, see\n    <a href=\"https://docs.docker.com/engine/reference/builder/#cmd\">https://docs.docker.com/engine/reference/builder/#cmd</a>.</p>"}))
    TaskContainerDetails.add_member(:depends_on, Smithy::Schema::Shapes::ShapeRef.new(shape: TaskContainerDependencyList, location_name: 'dependsOn', traits: {"smithy.api#documentation" => "<p>A list of containers that this container depends on.</p>"}))
    TaskContainerDetails.add_member(:environment, Smithy::Schema::Shapes::ShapeRef.new(shape: EnvironmentVariables, location_name: 'environment', traits: {"smithy.api#documentation" => "<p>The environment variables to pass to a container. This parameter maps to <code>Env</code> in\n   the <a href=\"https://docs.docker.com/engine/api/v1.23/#create-a-container\">Create a container</a> section of the <a href=\"https://docs.docker.com/engine/api/v1.23/\">Docker Remote API</a> and the\n    <code>--env</code> option to <a href=\"https://docs.docker.com/engine/reference/run/\">docker run</a>.</p>\n         <important>\n            <p>We don't recommend using plaintext environment variables for sensitive information, such as\n    credential data.</p>\n         </important>"}))
    TaskContainerDetails.add_member(:essential, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'essential', traits: {"smithy.api#documentation" => "<p>If the essential parameter of a container is marked as <code>true</code>, and that container\n   fails or stops for any reason, all other containers that are part of the task are stopped. If the\n    <code>essential</code> parameter of a container is marked as false, its failure doesn't affect\n   the rest of the containers in a task. If this parameter is omitted, a container is assumed to be\n   essential.</p>\n         <p>All jobs must have at least one essential container. If you have an application that's\n   composed of multiple containers, group containers that are used for a common purpose into\n   components, and separate the different components into multiple task definitions. For more\n   information, see <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/application_architecture.html\">Application\n    Architecture</a> in the <i>Amazon Elastic Container Service Developer Guide</i>.</p>"}))
    TaskContainerDetails.add_member(:firelens_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: FirelensConfiguration, location_name: 'firelensConfiguration', traits: {"smithy.api#documentation" => "<p>The FireLens configuration for the container. This is used to specify and configure a\n            log router for container logs. For more information, see <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/using_firelens.html\">Custom log</a> routing in the <i>Amazon Elastic Container Service Developer\n                    Guide</i>.</p>"}))
    TaskContainerDetails.add_member(:image, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'image', traits: {"smithy.api#documentation" => "<p>The image used to start a container. This string is passed directly to the Docker daemon. By\n   default, images in the Docker Hub registry are available. Other repositories are specified with\n   either <code>repository-url/image:tag</code> or <code>repository-url/image@digest</code>. Up to\n   255 letters (uppercase and lowercase), numbers, hyphens, underscores, colons, periods, forward\n   slashes, and number signs are allowed. This parameter maps to <code>Image</code> in the <a href=\"https://docs.docker.com/engine/api/v1.35/#operation/ContainerCreate\">Create a\n    container</a> section of the <a href=\"https://docs.docker.com/engine/api/v1.35/\">Docker\n    Remote API</a> and the <code>IMAGE</code> parameter of the <a href=\"https://docs.docker.com/engine/reference/run/#security-configuration\">\n               <i>docker\n     run</i>\n            </a>.</p>"}))
    TaskContainerDetails.add_member(:linux_parameters, Smithy::Schema::Shapes::ShapeRef.new(shape: LinuxParameters, location_name: 'linuxParameters', traits: {"smithy.api#documentation" => "<p>Linux-specific modifications that are applied to the container, such as Linux kernel\n   capabilities. For more information, see <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/APIReference/API_KernelCapabilities.html\">KernelCapabilities</a>.</p>\n         <note>\n            <p>This parameter is not supported for Windows containers.</p>\n         </note>"}))
    TaskContainerDetails.add_member(:log_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: LogConfiguration, location_name: 'logConfiguration', traits: {"smithy.api#documentation" => "<p>The log configuration specification for the container.</p>\n         <p>This parameter maps to <code>LogConfig</code> in the <a href=\"https://docs.docker.com/engine/api/v1.35/#operation/ContainerCreate\">Create a\n    container</a> section of the <a href=\"https://docs.docker.com/engine/api/v1.35/\">Docker\n    Remote API</a> and the <code>--log-driver</code> option to <a href=\"https://docs.docker.com/engine/reference/run/#security-configuration\">docker\n   run</a>.</p>\n         <p>By default, containers use the same logging driver that the Docker daemon uses. However the\n   container can use a different logging driver than the Docker daemon by specifying a log driver\n   with this parameter in the container definition. To use a different logging driver for a\n   container, the log system must be configured properly on the container instance (or on a\n   different log server for remote logging options). For more information about the options for\n   different supported log drivers, see <a href=\"https://docs.docker.com/engine/admin/logging/overview/\">Configure logging drivers </a>\n   in the <i>Docker documentation</i>.</p>\n         <note>\n            <p>Amazon ECS currently supports a subset of the logging drivers available to the Docker daemon\n    (shown in the <code>LogConfiguration</code> data type). Additional log drivers may be available\n    in future releases of the Amazon ECS container agent.</p>\n         </note>\n         <p>This parameter requires version 1.18 of the Docker Remote API or greater on your container\n   instance. To check the Docker Remote API version on your container instance, log in to your\n   container instance and run the following command: sudo docker version <code>--format\n    '{{.Server.APIVersion}}'</code>\n         </p>\n         <note>\n            <p>The Amazon ECS container agent running on a container instance must register the logging drivers\n    available on that instance with the <code>ECS_AVAILABLE_LOGGING_DRIVERS</code> environment\n    variable before containers placed on that instance can use these log configuration options. For\n    more information, see <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/ecs-agent-config.html\">Amazon ECS container agent\n     configuration</a> in the <i>Amazon Elastic Container Service Developer Guide</i>.</p>\n         </note>"}))
    TaskContainerDetails.add_member(:mount_points, Smithy::Schema::Shapes::ShapeRef.new(shape: MountPoints, location_name: 'mountPoints', traits: {"smithy.api#documentation" => "<p>The mount points for data volumes in your container.</p>\n         <p>This parameter maps to <code>Volumes</code> in the <a href=\"https://docs.docker.com/engine/api/v1.35/#operation/ContainerCreate\">Create a\n    container</a> section of the <a href=\"https://docs.docker.com/engine/api/v1.35/\">Docker\n    Remote API</a> and the <a href=\"\">--volume</a> option to <a href=\"https://docs.docker.com/engine/reference/run/#security-configuration\">docker\n   run</a>.</p>\n         <p>Windows containers can mount whole directories on the same drive as\n    <code>$env:ProgramData</code>. Windows containers can't mount directories on a different drive,\n   and mount point can't be across drives.</p>"}))
    TaskContainerDetails.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'name', traits: {"smithy.api#documentation" => "<p>The name of a container.</p>"}))
    TaskContainerDetails.add_member(:privileged, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'privileged', traits: {"smithy.api#documentation" => "<p>When this parameter is <code>true</code>, the container is given elevated privileges on the\n   host container instance (similar to the <code>root</code> user). This parameter maps to\n    <code>Privileged</code> in the <a href=\"https://docs.docker.com/engine/api/v1.35/#operation/ContainerCreate\">Create a\n    container</a> section of the <a href=\"https://docs.docker.com/engine/api/v1.35/\">Docker\n    Remote API</a> and the <code>--privileged</code> option to <a href=\"https://docs.docker.com/engine/reference/run/#security-configuration\">docker\n   run</a>.</p>\n         <note>\n            <p>This parameter is not supported for Windows containers or tasks run on Fargate.</p>\n         </note>"}))
    TaskContainerDetails.add_member(:readonly_root_filesystem, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'readonlyRootFilesystem', traits: {"smithy.api#documentation" => "<p>When this parameter is true, the container is given read-only access to its root file\n   system. This parameter maps to <code>ReadonlyRootfs</code> in the <a href=\"https://docs.docker.com/engine/api/v1.35/#operation/ContainerCreate\">Create a\n    container</a> section of the <a href=\"https://docs.docker.com/engine/api/v1.35/\">Docker\n    Remote API</a> and the <code>--read-only</code> option to <a href=\"https://docs.docker.com/engine/reference/run/#security-configuration\">docker\n   run</a>.</p>\n         <note>\n            <p>This parameter is not supported for Windows containers.</p>\n         </note>"}))
    TaskContainerDetails.add_member(:repository_credentials, Smithy::Schema::Shapes::ShapeRef.new(shape: RepositoryCredentials, location_name: 'repositoryCredentials', traits: {"smithy.api#documentation" => "<p>The private repository authentication credentials to use.</p>"}))
    TaskContainerDetails.add_member(:resource_requirements, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceRequirements, location_name: 'resourceRequirements', traits: {"smithy.api#documentation" => "<p>The type and amount of a resource to assign to a container. The only supported resource is a\n   GPU.</p>"}))
    TaskContainerDetails.add_member(:secrets, Smithy::Schema::Shapes::ShapeRef.new(shape: SecretList, location_name: 'secrets', traits: {"smithy.api#documentation" => "<p>The secrets to pass to the container. For more information, see <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/specifying-sensitive-data.html\">Specifying Sensitive\n    Data</a> in the Amazon Elastic Container Service Developer Guide.</p>"}))
    TaskContainerDetails.add_member(:ulimits, Smithy::Schema::Shapes::ShapeRef.new(shape: Ulimits, location_name: 'ulimits', traits: {"smithy.api#documentation" => "<p>A list of <code>ulimits</code> to set in the container. If a <code>ulimit</code> value is\n   specified in a task definition, it overrides the default values set by Docker. This parameter\n   maps to <code>Ulimits</code> in the <a href=\"https://docs.docker.com/engine/api/v1.35/#operation/ContainerCreate\">Create a\n    container</a> section of the <a href=\"https://docs.docker.com/engine/api/v1.35/\">Docker\n    Remote API</a> and the <code>--ulimit</code> option to <a href=\"https://docs.docker.com/engine/reference/run/#security-configuration\">docker\n   run</a>.</p>\n         <p>Amazon ECS tasks hosted on Fargate use the default resource limit values set by the operating\n   system with the exception of the nofile resource limit parameter which Fargate overrides. The\n    <code>nofile</code> resource limit sets a restriction on the number of open files that a\n   container can use. The default <code>nofile</code> soft limit is <code>1024</code> and the\n   default hard limit is <code>65535</code>.</p>\n         <p>This parameter requires version 1.18 of the Docker Remote API or greater on your container\n   instance. To check the Docker Remote API version on your container instance, log in to your\n   container instance and run the following command: sudo docker version <code>--format\n    '{{.Server.APIVersion}}'</code>\n         </p>\n         <note>\n            <p>This parameter is not supported for Windows containers.</p>\n         </note>"}))
    TaskContainerDetails.add_member(:user, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'user', traits: {"smithy.api#documentation" => "<p>The user to use inside the container. This parameter maps to User in the Create a container\n   section of the Docker Remote API and the --user option to docker run.</p>\n         <note>\n            <p>When running tasks using the <code>host</code> network mode, don't run containers using the\n     <code>root user (UID 0)</code>. We recommend using a non-root user for better security.</p>\n         </note>\n         <p>You can specify the <code>user</code> using the following formats. If specifying a UID or\n   GID, you must specify it as a positive integer.</p>\n         <ul>\n            <li>\n               <p>\n                  <code>user</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>user:group</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>uid</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>uid:gid</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>user:gi</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>uid:group</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code></code>\n               </p>\n            </li>\n         </ul>\n         <note>\n            <p>This parameter is not supported for Windows containers.</p>\n         </note>"}))
    TaskContainerDetails.add_member(:exit_code, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'exitCode', traits: {"smithy.api#documentation" => "<p>The exit code returned upon completion.</p>"}))
    TaskContainerDetails.add_member(:reason, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'reason', traits: {"smithy.api#documentation" => "<p>A short (255 max characters) human-readable string to provide additional details for a\n   running or stopped container.</p>"}))
    TaskContainerDetails.add_member(:log_stream_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'logStreamName', traits: {"smithy.api#documentation" => "<p>The name of the CloudWatch Logs log stream that's associated with the container. The log group for\n   Batch jobs is /aws/batch/job. Each container attempt receives a log stream name when they reach\n   the <code>RUNNING</code> status. </p>"}))
    TaskContainerDetails.add_member(:network_interfaces, Smithy::Schema::Shapes::ShapeRef.new(shape: NetworkInterfaceList, location_name: 'networkInterfaces', traits: {"smithy.api#documentation" => "<p>The network interfaces that are associated with the job.</p>"}))
    TaskContainerDetails.type = Types::TaskContainerDetails
    TaskContainerOverrides.add_member(:command, Smithy::Schema::Shapes::ShapeRef.new(shape: StringList, location_name: 'command', traits: {"smithy.api#documentation" => "<p>The command to send to the container that overrides the default command from the Docker\n   image or the job definition.</p>\n         <note>\n            <p>This parameter can't contain an empty string.</p>\n         </note>"}))
    TaskContainerOverrides.add_member(:environment, Smithy::Schema::Shapes::ShapeRef.new(shape: EnvironmentVariables, location_name: 'environment', traits: {"smithy.api#documentation" => "<p>The environment variables to send to the container. You can add new environment variables,\n   which are added to the container at launch, or you can override the existing environment\n   variables from the Docker image or the job definition.</p>\n         <note>\n            <p>Environment variables cannot start with <code>AWS_BATCH</code>. This naming convention is\n    reserved for variables that Batch sets.</p>\n         </note>"}))
    TaskContainerOverrides.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'name', traits: {"smithy.api#documentation" => "<p>A pointer to the container that you want to override. The container's name provides a unique\n   identifier for the container being used.</p>"}))
    TaskContainerOverrides.add_member(:resource_requirements, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceRequirements, location_name: 'resourceRequirements', traits: {"smithy.api#documentation" => "<p>The type and amount of resources to assign to a container. This overrides the settings in\n   the job definition. The supported resources include <code>GPU</code>, <code>MEMORY</code>, and\n    <code>VCPU</code>.</p>"}))
    TaskContainerOverrides.type = Types::TaskContainerOverrides
    TaskContainerProperties.add_member(:command, Smithy::Schema::Shapes::ShapeRef.new(shape: StringList, location_name: 'command', traits: {"smithy.api#documentation" => "<p>The command that's passed to the container. This parameter maps to <code>Cmd</code> in the\n    <a href=\"https://docs.docker.com/engine/api/v1.23/#create-a-container\">Create a\n    container</a> section of the <a href=\"https://docs.docker.com/engine/api/v1.23/\">Docker\n    Remote API</a> and the <code>COMMAND</code> parameter to <a href=\"https://docs.docker.com/engine/reference/run/\">docker run</a>. For more information,\n   see <a href=\"https://docs.docker.com/engine/reference/builder/#cmd\">Dockerfile reference:\n    CMD</a>.</p>"}))
    TaskContainerProperties.add_member(:depends_on, Smithy::Schema::Shapes::ShapeRef.new(shape: TaskContainerDependencyList, location_name: 'dependsOn', traits: {"smithy.api#documentation" => "<p>A list of containers that this container depends on.</p>"}))
    TaskContainerProperties.add_member(:environment, Smithy::Schema::Shapes::ShapeRef.new(shape: EnvironmentVariables, location_name: 'environment', traits: {"smithy.api#documentation" => "<p>The environment variables to pass to a container. This parameter maps to Env in the <a href=\"https://docs.docker.com/engine/api/v1.23/#create-a-container\">Create a container</a>\n   section of the <a href=\"https://docs.docker.com/engine/api/v1.23/\">Docker Remote API</a>\n   and the <code>--env</code> parameter to <a href=\"https://docs.docker.com/engine/reference/run/\">docker run</a>. </p>\n         <important>\n            <p>We don't recommend using plaintext environment variables for sensitive information, such as\n    credential data.</p>\n         </important>\n         <note>\n            <p>Environment variables cannot start with <code>AWS_BATCH</code>. This naming convention is\n    reserved for variables that Batch sets.</p>\n         </note>"}))
    TaskContainerProperties.add_member(:essential, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'essential', traits: {"smithy.api#documentation" => "<p>If the essential parameter of a container is marked as <code>true</code>, and that container\n   fails or stops for any reason, all other containers that are part of the task are stopped. If the\n    <code>essential</code> parameter of a container is marked as false, its failure doesn't affect\n   the rest of the containers in a task. If this parameter is omitted, a container is assumed to be\n   essential.</p>\n         <p>All jobs must have at least one essential container. If you have an application that's\n   composed of multiple containers, group containers that are used for a common purpose into\n   components, and separate the different components into multiple task definitions. For more\n   information, see <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/application_architecture.html\">Application\n    Architecture</a> in the <i>Amazon Elastic Container Service Developer Guide</i>.</p>"}))
    TaskContainerProperties.add_member(:firelens_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: FirelensConfiguration, location_name: 'firelensConfiguration', traits: {"smithy.api#documentation" => "<p>The FireLens configuration for the container. This is used to specify and configure a\n            log router for container logs. For more information, see <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/using_firelens.html\">Custom log</a> routing in the <i>Amazon Elastic Container Service Developer\n                    Guide</i>.</p>"}))
    TaskContainerProperties.add_member(:image, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'image', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The image used to start a container. This string is passed directly to the Docker daemon. By\n   default, images in the Docker Hub registry are available. Other repositories are specified with\n   either <code>repository-url/image:tag</code> or <code>repository-url/image@digest</code>. Up to\n   255 letters (uppercase and lowercase), numbers, hyphens, underscores, colons, periods, forward\n   slashes, and number signs are allowed. This parameter maps to <code>Image</code> in the <a href=\"https://docs.docker.com/engine/api/v1.35/#operation/ContainerCreate\">Create a\n    container</a> section of the <a href=\"https://docs.docker.com/engine/api/v1.35/\">Docker\n    Remote API</a> and the <code>IMAGE</code> parameter of the <a href=\"https://docs.docker.com/engine/reference/run/#security-configuration\">\n               <i>docker\n     run</i>\n            </a>.</p>", "smithy.api#required" => {}}))
    TaskContainerProperties.add_member(:linux_parameters, Smithy::Schema::Shapes::ShapeRef.new(shape: LinuxParameters, location_name: 'linuxParameters', traits: {"smithy.api#documentation" => "<p>Linux-specific modifications that are applied to the container, such as Linux kernel\n   capabilities. For more information, see <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/APIReference/API_KernelCapabilities.html\">KernelCapabilities</a>.</p>"}))
    TaskContainerProperties.add_member(:log_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: LogConfiguration, location_name: 'logConfiguration', traits: {"smithy.api#documentation" => "<p>The log configuration specification for the container.</p>\n         <p>This parameter maps to <code>LogConfig</code> in the <a href=\"https://docs.docker.com/engine/api/v1.35/#operation/ContainerCreate\">Create a\n    container</a> section of the <a href=\"https://docs.docker.com/engine/api/v1.35/\">Docker\n    Remote API</a> and the <code>--log-driver</code> option to <a href=\"https://docs.docker.com/engine/reference/run/#security-configuration\">docker\n   run</a>.</p>\n         <p>By default, containers use the same logging driver that the Docker daemon uses. However the\n   container can use a different logging driver than the Docker daemon by specifying a log driver\n   with this parameter in the container definition. To use a different logging driver for a\n   container, the log system must be configured properly on the container instance (or on a\n   different log server for remote logging options). For more information about the options for\n   different supported log drivers, see <a href=\"https://docs.docker.com/engine/admin/logging/overview/\">Configure logging drivers </a>\n   in the <i>Docker documentation</i>.</p>\n         <note>\n            <p>Amazon ECS currently supports a subset of the logging drivers available to the Docker daemon\n    (shown in the <code>LogConfiguration</code> data type). Additional log drivers may be available\n    in future releases of the Amazon ECS container agent.</p>\n         </note>\n         <p>This parameter requires version 1.18 of the Docker Remote API or greater on your container\n   instance. To check the Docker Remote API version on your container instance, log in to your\n   container instance and run the following command: sudo docker version <code>--format\n    '{{.Server.APIVersion}}'</code>\n         </p>\n         <note>\n            <p>The Amazon ECS container agent running on a container instance must register the logging drivers\n    available on that instance with the <code>ECS_AVAILABLE_LOGGING_DRIVERS</code> environment\n    variable before containers placed on that instance can use these log configuration options. For\n    more information, see <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/ecs-agent-config.html\">Amazon ECS container agent\n     configuration</a> in the <i>Amazon Elastic Container Service Developer Guide</i>.</p>\n         </note>"}))
    TaskContainerProperties.add_member(:mount_points, Smithy::Schema::Shapes::ShapeRef.new(shape: MountPoints, location_name: 'mountPoints', traits: {"smithy.api#documentation" => "<p>The mount points for data volumes in your container.</p>\n         <p>This parameter maps to <code>Volumes</code> in the <a href=\"https://docs.docker.com/engine/api/v1.35/#operation/ContainerCreate\">Create a\n    container</a> section of the <a href=\"https://docs.docker.com/engine/api/v1.35/\">Docker\n    Remote API</a> and the <a href=\"\">--volume</a> option to <a href=\"https://docs.docker.com/engine/reference/run/#security-configuration\">docker\n   run</a>.</p>\n         <p>Windows containers can mount whole directories on the same drive as\n    <code>$env:ProgramData</code>. Windows containers can't mount directories on a different drive,\n   and mount point can't be across drives.</p>"}))
    TaskContainerProperties.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'name', traits: {"smithy.api#documentation" => "<p>The name of a container. The name can be used as a unique identifier to target your\n    <code>dependsOn</code> and <code>Overrides</code> objects. </p>"}))
    TaskContainerProperties.add_member(:privileged, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'privileged', traits: {"smithy.api#documentation" => "<p>When this parameter is <code>true</code>, the container is given elevated privileges on the\n   host container instance (similar to the <code>root</code> user). This parameter maps to\n    <code>Privileged</code> in the <a href=\"https://docs.docker.com/engine/api/v1.35/#operation/ContainerCreate\">Create a\n    container</a> section of the <a href=\"https://docs.docker.com/engine/api/v1.35/\">Docker\n    Remote API</a> and the <code>--privileged</code> option to <a href=\"https://docs.docker.com/engine/reference/run/#security-configuration\">docker\n   run</a>.</p>\n         <note>\n            <p>This parameter is not supported for Windows containers or tasks run on Fargate.</p>\n         </note>"}))
    TaskContainerProperties.add_member(:readonly_root_filesystem, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'readonlyRootFilesystem', traits: {"smithy.api#documentation" => "<p>When this parameter is true, the container is given read-only access to its root file\n   system. This parameter maps to <code>ReadonlyRootfs</code> in the <a href=\"https://docs.docker.com/engine/api/v1.35/#operation/ContainerCreate\">Create a\n    container</a> section of the <a href=\"https://docs.docker.com/engine/api/v1.35/\">Docker\n    Remote API</a> and the <code>--read-only</code> option to <a href=\"https://docs.docker.com/engine/reference/run/#security-configuration\">docker\n   run</a>.</p>\n         <note>\n            <p>This parameter is not supported for Windows containers.</p>\n         </note>"}))
    TaskContainerProperties.add_member(:repository_credentials, Smithy::Schema::Shapes::ShapeRef.new(shape: RepositoryCredentials, location_name: 'repositoryCredentials', traits: {"smithy.api#documentation" => "<p>The private repository authentication credentials to use.</p>"}))
    TaskContainerProperties.add_member(:resource_requirements, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceRequirements, location_name: 'resourceRequirements', traits: {"smithy.api#documentation" => "<p>The type and amount of a resource to assign to a container. The only supported resource is a\n   GPU.</p>"}))
    TaskContainerProperties.add_member(:secrets, Smithy::Schema::Shapes::ShapeRef.new(shape: SecretList, location_name: 'secrets', traits: {"smithy.api#documentation" => "<p>The secrets to pass to the container. For more information, see <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/specifying-sensitive-data.html\">Specifying Sensitive\n    Data</a> in the Amazon Elastic Container Service Developer Guide.</p>"}))
    TaskContainerProperties.add_member(:ulimits, Smithy::Schema::Shapes::ShapeRef.new(shape: Ulimits, location_name: 'ulimits', traits: {"smithy.api#documentation" => "<p>A list of <code>ulimits</code> to set in the container. If a <code>ulimit</code> value is\n   specified in a task definition, it overrides the default values set by Docker. This parameter\n   maps to <code>Ulimits</code> in the <a href=\"https://docs.docker.com/engine/api/v1.35/#operation/ContainerCreate\">Create a\n    container</a> section of the <a href=\"https://docs.docker.com/engine/api/v1.35/\">Docker\n    Remote API</a> and the <code>--ulimit</code> option to <a href=\"https://docs.docker.com/engine/reference/run/#security-configuration\">docker\n   run</a>.</p>\n         <p>Amazon ECS tasks hosted on Fargate use the default resource limit values set by the operating\n   system with the exception of the nofile resource limit parameter which Fargate overrides. The\n    <code>nofile</code> resource limit sets a restriction on the number of open files that a\n   container can use. The default <code>nofile</code> soft limit is <code>1024</code> and the\n   default hard limit is <code>65535</code>.</p>\n         <p>This parameter requires version 1.18 of the Docker Remote API or greater on your container\n   instance. To check the Docker Remote API version on your container instance, log in to your\n   container instance and run the following command: sudo docker version <code>--format\n    '{{.Server.APIVersion}}'</code>\n         </p>\n         <note>\n            <p>This parameter is not supported for Windows containers.</p>\n         </note>"}))
    TaskContainerProperties.add_member(:user, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'user', traits: {"smithy.api#documentation" => "<p>The user to use inside the container. This parameter maps to User in the Create a container\n   section of the Docker Remote API and the --user option to docker run.</p>\n         <note>\n            <p>When running tasks using the <code>host</code> network mode, don't run containers using the\n     <code>root user (UID 0)</code>. We recommend using a non-root user for better security.</p>\n         </note>\n         <p>You can specify the <code>user</code> using the following formats. If specifying a UID or\n   GID, you must specify it as a positive integer.</p>\n         <ul>\n            <li>\n               <p>\n                  <code>user</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>user:group</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>uid</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>uid:gid</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>user:gi</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>uid:group</code>\n               </p>\n            </li>\n         </ul>\n         <note>\n            <p>This parameter is not supported for Windows containers.</p>\n         </note>"}))
    TaskContainerProperties.type = Types::TaskContainerProperties
    TaskPropertiesOverride.add_member(:containers, Smithy::Schema::Shapes::ShapeRef.new(shape: ListTaskContainerOverrides, location_name: 'containers', traits: {"smithy.api#documentation" => "<p>The overrides for the container definition of a job.</p>"}))
    TaskPropertiesOverride.type = Types::TaskPropertiesOverride
    TerminateJobRequest.add_member(:job_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'jobId', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The Batch job ID of the job to terminate.</p>", "smithy.api#required" => {}}))
    TerminateJobRequest.add_member(:reason, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'reason', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>A message to attach to the job that explains the reason for canceling it. This message is\n      returned by future <a>DescribeJobs</a> operations on the job. It is also\n      recorded in the Batch activity logs.</p>\n         <p>This parameter has as limit of 1024 characters.</p>", "smithy.api#required" => {}}))
