    TerminateServiceJobRequest.add_member(:job_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'jobId', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The service job ID of the service job to terminate.</p>", "smithy.api#required" => {}}))
    TerminateServiceJobRequest.add_member(:reason, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'reason', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>A message to attach to the service job that explains the reason for canceling it. This message is returned by <code>DescribeServiceJob</code> operations on the service job.</p>", "smithy.api#required" => {}}))
    TerminateServiceJobRequest.type = Types::TerminateServiceJobRequest
    TerminateServiceJobResponse.type = Types::TerminateServiceJobResponse
    Tmpfs.add_member(:container_path, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'containerPath', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The absolute file path in the container where the <code>tmpfs</code> volume is\n   mounted.</p>", "smithy.api#required" => {}}))
    Tmpfs.add_member(:size, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'size', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The size (in MiB) of the <code>tmpfs</code> volume.</p>", "smithy.api#required" => {}}))
    Tmpfs.add_member(:mount_options, Smithy::Schema::Shapes::ShapeRef.new(shape: StringList, location_name: 'mountOptions', traits: {"smithy.api#documentation" => "<p>The list of <code>tmpfs</code> volume mount options.</p>\n         <p>Valid values: \"<code>defaults</code>\" | \"<code>ro</code>\" | \"<code>rw</code>\" |\n    \"<code>suid</code>\" | \"<code>nosuid</code>\" | \"<code>dev</code>\" | \"<code>nodev</code>\" |\n    \"<code>exec</code>\" | \"<code>noexec</code>\" | \"<code>sync</code>\" | \"<code>async</code>\" |\n    \"<code>dirsync</code>\" | \"<code>remount</code>\" | \"<code>mand</code>\" | \"<code>nomand</code>\" |\n    \"<code>atime</code>\" | \"<code>noatime</code>\" | \"<code>diratime</code>\" |\n    \"<code>nodiratime</code>\" | \"<code>bind</code>\" | \"<code>rbind\" | \"unbindable\" | \"runbindable\" |\n    \"private\" | \"rprivate\" | \"shared\" | \"rshared\" | \"slave\" | \"rslave\" | \"relatime</code>\" |\n    \"<code>norelatime</code>\" | \"<code>strictatime</code>\" | \"<code>nostrictatime</code>\" |\n    \"<code>mode</code>\" | \"<code>uid</code>\" | \"<code>gid</code>\" | \"<code>nr_inodes</code>\" |\n    \"<code>nr_blocks</code>\" | \"<code>mpol</code>\"</p>"}))
    Tmpfs.type = Types::Tmpfs
    TmpfsList.member = Smithy::Schema::Shapes::ShapeRef.new(shape: Tmpfs)
    Ulimit.add_member(:hard_limit, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'hardLimit', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The hard limit for the <code>ulimit</code> type. </p>", "smithy.api#required" => {}}))
    Ulimit.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'name', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The <code>type</code> of the <code>ulimit</code>. Valid values are: <code>core</code> |\n    <code>cpu</code> | <code>data</code> | <code>fsize</code> | <code>locks</code> |\n    <code>memlock</code> | <code>msgqueue</code> | <code>nice</code> | <code>nofile</code> |\n    <code>nproc</code> | <code>rss</code> | <code>rtprio</code> | <code>rttime</code> |\n    <code>sigpending</code> | <code>stack</code>.</p>", "smithy.api#required" => {}}))
    Ulimit.add_member(:soft_limit, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'softLimit', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The soft limit for the <code>ulimit</code> type.</p>", "smithy.api#required" => {}}))
    Ulimit.type = Types::Ulimit
    Ulimits.member = Smithy::Schema::Shapes::ShapeRef.new(shape: Ulimit)
    UntagResourceRequest.add_member(:resource_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'resourceArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the resource from which to delete tags. Batch resources that support tags are compute environments, jobs, job definitions, job queues,\n and scheduling policies. ARNs for child jobs of array and multi-node parallel (MNP) jobs aren't supported.</p>", "smithy.api#httpLabel" => {}, "smithy.api#required" => {}}))
    UntagResourceRequest.add_member(:tag_keys, Smithy::Schema::Shapes::ShapeRef.new(shape: TagKeysList, location_name: 'tagKeys', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The keys of the tags to be removed.</p>", "smithy.api#httpQuery" => "tagKeys", "smithy.api#required" => {}}))
