    UpdateConsumableResourceRequest.add_member(:operation, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'operation', traits: {"smithy.api#documentation" => "<p>Indicates how the quantity of the consumable resource will be updated. Must be one of:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>SET</code>\n               </p>\n               <p>Sets the quantity of the resource to the value specified by the <code>quantity</code>\n                    parameter.</p>\n            </li>\n            <li>\n               <p>\n                  <code>ADD</code>\n               </p>\n               <p>Increases the quantity of the resource by the value specified by the <code>quantity</code>\n                    parameter.</p>\n            </li>\n            <li>\n               <p>\n                  <code>REMOVE</code>\n               </p>\n               <p>Reduces the quantity of the resource by the value specified by the <code>quantity</code>\n                    parameter.</p>\n            </li>\n         </ul>"}))
    UpdateConsumableResourceRequest.add_member(:quantity, Smithy::Schema::Shapes::ShapeRef.new(shape: Long, location_name: 'quantity', traits: {"smithy.api#documentation" => "<p>The change in the total quantity of the consumable resource. The <code>operation</code>\n            parameter determines whether the value specified here will be the new total quantity, or\n            the amount by which the total quantity will be increased or reduced. Must be a non-negative \n            value.</p>"}))
